// Üretilen dosya: tool/ozgun/uret.py. Araştırma Yöntemleri · Gözlem, anket, görüşme ve örnekleme yöntemleri (senaryolarla) (kolay).
const ozResearch3Kolay = <(String, String, List<String>, String)>[
  ('Bir araştırmacının, insanların ne söylediğine değil doğrudan ne yaptığına dair veri toplamak istediği durumda en uygun yöntem hangisidir?', 'Gözlem', ['Anket', 'Yapılandırılmış görüşme', 'Odak grup görüşmesi'], 'Gözlem, davranışı kişinin kendi beyanına dayanmadan, gerçekleştiği anda kaydeder. Anket ve görüşmeler ise kişilerin söylediklerine dayanır.'),
  ('Gözlem yönteminin anket yöntemine göre en belirgin üstünlüğü aşağıdakilerden hangisidir?', 'Söylenen ile yapılan arasındaki farkı ortaya çıkarabilmesi', ['Çok sayıda kişiye aynı anda ve kısa sürede ulaşabilmesi', 'Kişilerin geçmiş deneyimlerini kolayca öğrenebilmesi', 'Düşünce ve tutumları doğrudan ölçebilmesi'], 'İnsanlar ankette yaptıklarını olduğundan farklı anlatabilir; gözlem davranışın kendisini kaydettiği için bu farkı yakalayabilir.'),
  ('Bir antropoloğun bir köyde bir yıl yaşayıp köylülerle birlikte tarlada çalışarak onların günlük yaşamını kaydetmesi hangi gözlem türüne örnektir?', 'Katılımlı gözlem', ['Katılımsız gözlem', 'Laboratuvar gözlemi', 'Yapılandırılmış gözlem'], 'Araştırmacı incelediği topluluğun etkinliklerine bizzat katılarak gözlem yaptığı için bu katılımlı gözlemdir.'),
  ('Katılımlı gözlemin temel güçlü yanı aşağıdakilerden hangisidir?', 'Grubun bakış açısını içeriden anlamayı sağlaması', ['Sonuçların büyük evrenlere kolayca genellenebilmesi', 'Gözlemcinin hiçbir şekilde grubu etkilememesi', 'Verilerin hızlı ve düşük maliyetle toplanması'], 'Katılımlı gözlemde araştırmacı grubun içinde yaşadığı için olayları üyelerin gözünden anlamlandırabilir. Genelleme gücü ve hızı ise sınırlıdır.'),
  ('Bir araştırmacı bir ilkokulun bahçesini tel örgünün dışından izleyerek çocukların oyun gruplarını not ediyor; çocuklarla hiç konuşmuyor. Bu hangi gözlem türüdür?', 'Katılımsız gözlem', ['Katılımlı gözlem', 'Derinlemesine görüşme', 'Odak grup çalışması'], 'Araştırmacı etkinliğe dahil olmadan dışarıdan izlediği için gözlem katılımsızdır.'),
  ('Bir trafik mühendisinin bir kavşaktaki araç geçişlerini kamerayla kaydedip sayması, gözlemci rolü bakımından nasıl nitelendirilir?', 'Katılımsız gözlem', ['Katılımlı gözlem', 'Katılımcı olarak gözlemci', 'Tam katılımcı rolü'], 'Mühendis trafiğin bir parçası olmadan yalnızca kayıt aldığı için katılımsız gözlem yapmaktadır.'),
  ('Bir araştırmacı bir derneğin toplantılarına, üyelere kendini araştırmacı olarak tanıtıp izin alarak katılıyor ve not tutuyor. Bu gözlem hangi bakımdan nitelendirilir?', 'Açık gözlem', ['Gizli gözlem', 'Laboratuvar gözlemi', 'Tam gözlemci rolü'], 'Katılımcılar araştırmanın varlığından haberdar olduğu ve izin verdiği için bu açık (bildirilen) gözlemdir.'),
  ('Bir gözlemcinin önceden hazırlanmış bir listede yer alan belirli davranışları (el kaldırma, söz kesme, soru sorma) işaretleyerek kaydettiği gözlem türü hangisidir?', 'Yapılandırılmış gözlem', ['Yapılandırılmamış gözlem', 'Derinlemesine görüşme', 'Yaşam öyküsü çalışması'], 'Kaydedilecek davranışların önceden tanımlandığı ve bir form üzerinde işaretlendiği gözlem yapılandırılmış gözlemdir.'),
  ('Yapılandırılmış gözlemin en önemli avantajı aşağıdakilerden hangisidir?', 'Farklı gözlemcilerin verilerinin karşılaştırılabilmesi', ['Beklenmedik olayların ayrıntılı biçimde yakalanması', 'Katılımcıların duygularının doğrudan ölçülmesi', 'Gözlem öncesi hiçbir hazırlık gerektirmemesi'], 'Ortak kategoriler kullanıldığı için veriler sayısallaştırılabilir ve gözlemciler arasında karşılaştırılabilir. Beklenmedik olayları yakalamak ise yapılandırılmamış gözlemin gücüdür.'),
  ('Alan notlarının gözlemden mümkün olduğunca kısa süre sonra yazıya geçirilmesi neden önerilir?', 'Ayrıntılar unutulmadan ve bellek çarpıtmadan önce kaydedilsin diye', ['Katılımcılar notları gözlemin hemen ardından okuyup onaylayabilsin diye', 'Gözlem süresi resmi olarak kısaltılabilsin diye', 'Notların sayısı yapay olarak artırılsın diye'], 'Bellek zamanla ayrıntıları kaybeder ve olayları yeniden yorumlar; erken kayıt verinin doğruluğunu korur.'),
  ('Bir psikoloğun çocukların oyuncak paylaşma davranışını, oyuncakların ve sürenin önceden belirlendiği tek yönlü aynalı bir odada izlemesi hangi gözlem ortamına örnektir?', 'Kontrollü (laboratuvar) gözlem', ['Doğal ortamda yapılan gözlem', 'Katılımlı alan gözlemi', 'Etnografik gözlem'], 'Ortam koşulları araştırmacı tarafından düzenlendiği için bu kontrollü gözlemdir; doğal gözlemde davranış kendi olağan ortamında izlenir.'),
  ('Doğal ortamda gözlemin kontrollü ortamda gözleme göre temel üstünlüğü nedir?', 'Davranışın gerçek yaşamdaki hâline daha yakın olması', ['Koşulların tüm katılımcılar için aynı tutulabilmesi', 'Gözlemin istenildiği zaman tekrarlanabilmesi', 'Dış etkenlerin tamamen dışlanabilmesi'], 'Doğal ortamda davranış olağan bağlamında gerçekleştiği için bulgular gerçek yaşamı daha iyi yansıtır. Diğer seçenekler kontrollü ortamın üstünlükleridir.'),
  ('İnsanların gözlendiklerini fark ettiklerinde davranışlarını değiştirmesine genel olarak ne ad verilir?', 'Gözlemci etkisi', ['Örnekleme hatası', 'Kapsam hatası', 'Kartopu etkisi'], 'Gözlemci etkisi (tepkisellik), gözlenen kişilerin gözlemcinin varlığına tepki olarak olağan davranışlarından uzaklaşmasıdır.'),
  ('Bir müfettiş sınıfa girdiğinde öğrencilerin her zamankinden daha sessiz ve düzenli olması, gözlem verisi açısından neyi düşündürür?', 'Kaydedilen davranışın sınıfın olağan hâlini yansıtmayabileceğini', ['Sınıfın her zaman bu kadar düzenli olduğunu', 'Öğretmenin yöntemlerinin kesin olarak etkili olduğunu', 'Gözlem formunun yanlış hazırlandığını'], 'Gözlemcinin varlığı davranışı değiştirmiş olabilir; bu nedenle o derste görülen düzen olağan durumu temsil etmeyebilir.'),
  ('Gözlemci etkisini azaltmak için en yaygın kullanılan önlem aşağıdakilerden hangisidir?', 'Veri kaydına başlamadan önce katılımcıların gözlemcinin varlığına alışmasını beklemek', ['Gözlem süresini birkaç dakikayla sınırlamak', 'Gözlemcinin gördüğü her davranışı katılımcılar duyacak biçimde yorumlaması', 'Gözlemi her gün farklı bir gözlemcinin yapması'], 'Bir alışma döneminden sonra katılımcılar gözlemciyi önemsemez hâle gelir ve davranışları olağan düzeyine döner.'),
  ('Bir öğretmen yalnızca sınıfta bir kavga çıktığında kaydını tutuyor; kavganın nasıl başladığını, kaç dakika sürdüğünü ve nasıl bittiğini not ediyor. Bu kayıt yöntemi hangisidir?', 'Olay örneklemesi', ['Zaman örneklemesi', 'Sistematik örnekleme', 'Yarı yapılandırılmış görüşme'], 'Olay örneklemesinde gözlemci belirli bir olay türü ortaya çıktığında onu baştan sona kaydeder.'),
  ('Bir beden eğitimi öğretmeni öğrencilerin \'topu sektirebiliyor\', \'pas verebiliyor\' gibi becerilere sahip olup olmadığını yalnızca evet-hayır biçiminde işaretliyor. Kullandığı araç hangisidir?', 'Kontrol listesi', ['Derecelendirme ölçeği', 'Anekdot kaydı', 'Alan günlüğü'], 'Kontrol listesi bir davranışın varlığını ya da yokluğunu kaydeder; derecelendirme ölçeği ise davranışın düzeyini derecelendirir.'),
  ('Bir öğretmenin bir öğrenciyle ilgili dikkat çekici bir olayı olduğu gibi, kısa ve tarihli biçimde yazıya geçirmesine ne ad verilir?', 'Anekdot kaydı', ['Kontrol listesi', 'Derecelendirme ölçeği', 'Zaman örneklemesi'], 'Anekdot kaydı, gözlenen anlamlı bir olayın olgusal ve kısa bir betimlemesidir.'),
  ('Bir kültürel grubun yaşam biçimini, uzun süreli alan çalışması ve katılımlı gözlemle bütüncül biçimde betimlemeyi amaçlayan araştırma yaklaşımı hangisidir?', 'Etnografi', ['Kesitsel anket', 'Delphi tekniği', 'Kota örneklemesi'], 'Etnografi, bir topluluğun kültürünü içeriden ve uzun süreli alan çalışmasıyla betimleyen nitel bir yaklaşımdır.'),
  ('Bir araştırmacı bir mahalle kahvehanesinde altı ay boyunca vakit geçirip sohbetlere katılıyor, gözlem notları tutuyor ve müdavimlerle uzun söyleşiler yapıyor. Bu çalışmanın türü en iyi nasıl nitelendirilir?', 'Etnografik alan çalışması', ['Kesitsel anket araştırması', 'Laboratuvar gözlemi', 'Tabakalı örnekleme çalışması'], 'Uzun süreli bulunma, katılımlı gözlem ve derinlemesine söyleşilerin birlikte kullanılması etnografik alan çalışmasının özelliğidir.'),
  ('Bir kütüphanenin kullanım yoğunluğunu gözlemle ölçmek isteyen bir araştırmacının yalnızca pazartesi sabahları gözlem yapması neden sorunludur?', 'Diğer gün ve saatlerdeki kullanım farklı olabilir', ['Pazartesi sabahları gözlem yapmak yasaktır', 'Bu durumda gözlemci etkisi her zaman artar', 'Sabah saatlerinde veri kodlanamaz'], 'Gözlem zamanları da örneklenmelidir; tek bir zaman dilimi haftanın tamamındaki kullanım örüntüsünü yansıtmaz.'),
  ('Gözlem verilerini video kaydıyla toplamanın elle not almaya göre temel avantajı nedir?', 'Kaydın tekrar tekrar izlenip farklı kodlayıcılarca incelenebilmesi', ['Katılımcıların kameranın varlığından hiçbir şekilde etkilenmemesi', 'Etik onam gereksinimini ortadan kaldırması', 'Kodlama işini tamamen gereksiz kılması'], 'Video, aynı olayın birden çok kez ve birden çok kişi tarafından kodlanmasına olanak verir; ancak onam gerektirir ve katılımcıları etkileyebilir.'),
  ('Bir belediye, 80.000 hanenin toplu taşıma memnuniyetini birkaç hafta içinde ve düşük maliyetle öğrenmek istiyor. En uygun veri toplama yöntemi hangisidir?', 'Anket', ['Her haneyle derinlemesine görüşme', 'Uzun süreli katılımlı gözlem', 'Birkaç hanede yaşam öyküsü çalışması'], 'Çok sayıda kişiden aynı sorulara kısa sürede yanıt toplamak için en elverişli yöntem ankettir.'),
  ('Ankette tüm katılımcılara aynı soruların aynı sırayla ve aynı ifadelerle sorulması öncelikle neyi sağlar?', 'Yanıtların karşılaştırılabilir olmasını', ['Katılımcıların ankete daha istekli biçimde ve hızla katılmasını', 'Sosyal beğenirlik eğiliminin bütünüyle ve kesin olarak ortadan kalkmasını', 'Örneklem çerçevesindeki tüm eksiklerin otomatik biçimde düzelmesini'], 'Standartlaştırma, yanıtlar arasındaki farkların soru farklılığından değil kişiler arasındaki gerçek farklardan kaynaklanmasını amaçlar.'),
  ('Bir anket sorusunda \'Bu dersi neden seçtiniz?\' diye sorulup katılımcının yanıtı kendi cümleleriyle yazması bekleniyor. Bu soru türü hangisidir?', 'Açık uçlu soru', ['Kapalı uçlu soru', 'Likert tipi madde', 'Sıralama sorusu'], 'Açık uçlu sorularda hazır seçenek sunulmaz; katılımcı yanıtını kendi ifadeleriyle verir.'),
  ('Kapalı uçlu soruların açık uçlu sorulara göre temel avantajı nedir?', 'Yanıtların hızla kodlanıp sayısal olarak çözümlenebilmesi', ['Katılımcının akla gelmeyen düşüncelerini ayrıntılarıyla ortaya koyabilmesi', 'Araştırmacının önceden hiçbir seçenek düşünmek zorunda kalmaması', 'Katılımcıların kendi ifadelerini ve kelimelerini serbestçe kullanabilmesi'], 'Hazır seçenekler yanıtların doğrudan sayılmasını ve karşılaştırılmasını sağlar; ancak katılımcıyı sunulan seçeneklerle sınırlar.'),
  ('Bir araştırmacı gençlerin boş zamanlarında neler yaptığına dair hiçbir ön çalışma bulunmadığını fark ediyor. Pilot anketinde bu konuyu hangi soru türüyle sorması daha akıllıcadır?', 'Açık uçlu soruyla', ['Yalnızca evet-hayır seçenekli soruyla', 'Beş basamaklı Likert maddesiyle', 'Önceden belirlenmiş dört seçenekli soruyla'], 'Olası yanıtlar bilinmediğinde açık uçlu sorular yanıt yelpazesini ortaya çıkarır; bu yanıtlar daha sonra kapalı uçlu seçeneklere dönüştürülebilir.'),
  ('Kapalı uçlu bir soruya \'Diğer (belirtiniz): ……\' seçeneği eklemenin amacı nedir?', 'Sunulan seçeneklere uymayan yanıtları da yakalamak', ['Katılımcıyı en çok seçilen seçeneğe doğru yönlendirip yanıtları birleştirmek', 'Sorunun yanıtlanma süresini uzatmak', 'Anketin toplam uzunluğunu azaltmak'], '\'Diğer\' seçeneği, araştırmacının öngörmediği yanıtların kaybolmasını önler ve seçenek listesinin eksiklerini ortaya çıkarır.'),
  ('\'Kesinlikle katılmıyorum\'dan \'Kesinlikle katılıyorum\'a uzanan beş basamaklı yanıt seçenekleri hangi ölçek türüne aittir?', 'Likert tipi ölçek', ['Guttman ölçeği', 'Anlamsal farklılık ölçeği', 'Thurstone ölçeği'], 'Likert ölçeğinde katılımcı bir ifadeye katılma derecesini, genellikle beş ya da yedi basamaklı bir ölçek üzerinde belirtir.'),
  ('Bir ankette katılımcılardan beş tatil yerini en çok tercih ettiklerinden en az tercih ettiklerine doğru 1\'den 5\'e kadar numaralandırmaları isteniyor. Bu soru biçimi hangisidir?', 'Sıralama sorusu', ['Likert maddesi', 'Açık uçlu soru', 'Çoktan seçmeli tek yanıtlı soru'], 'Sıralama sorularında katılımcı seçenekleri birbirine göre öncelik sırasına koyar.'),
  ('\'Bu güzel parkın kapatılmasına karşı mısınız?\' sorusundaki temel sorun nedir?', 'Soru katılımcıyı belirli bir yanıta yönlendirmektedir', ['Soru birden fazla dilde ve karışık biçimde yazılmıştır', 'Soru açık uçlu olduğu için kodlanamaz', 'Soru katılımcının yaşını sormaktadır'], '\'Güzel\' nitelemesi ve sorunun kuruluşu, katılımcıyı parkın kapatılmasına karşı çıkmaya doğru iter; bu yönlendirici bir sorudur.'),
  ('Bir anket sorusu \'Okul kantininin fiyatlarından ve temizliğinden memnun musunuz?\' biçiminde yazılmıştır. Bu sorunun temel kusuru nedir?', 'Tek soruda iki ayrı konu sorulmaktadır', ['Soru gereksiz derecede kısa tutulmuştur', 'Soru yalnızca öğretmenlere yöneliktir', 'Soru açık uçlu olarak yazılmıştır'], 'Fiyattan memnun olup temizlikten memnun olmayan biri bu soruya doğru yanıt veremez; bu bir çift namlulu sorudur.'),
  ('Çift namlulu bir soruyu düzeltmenin en doğru yolu hangisidir?', 'Soruyu her biri tek bir konuyu soran iki ayrı soruya bölmek', ['Soruya bir \'Kararsızım\' seçeneği ekleyip soruyu aynen bırakmak', 'Soruyu anketin en sonuna taşıyıp aynı biçimde sormak', 'Sorunun yanıt seçeneklerini beşten yediye çıkarmak'], 'Her soru tek bir konuyu sormalıdır; iki konuyu ayrı sorulara bölmek her birine ayrı ve anlamlı yanıt verilmesini sağlar.'),
  ('Bir ankette yaş sorusunun seçenekleri \'15–20\', \'20–25\', \'25–30\' biçiminde verilmiştir. Bu seçeneklerin temel kusuru nedir?', 'Seçenekler birbiriyle çakışmaktadır', ['Seçenekler gereğinden fazla sayıda ve birbirinden çok farklı uzunluktadır', 'Seçenekler yalnızca kadın katılımcılar düşünülerek hazırlanmıştır', 'Seçenekler sayısal olmadığı için hiçbir biçimde karşılaştırılamaz'], '20 ya da 25 yaşındaki biri iki seçeneğe birden uyar; seçenekler karşılıklı dışlayıcı olmalıdır (ör. 15–19, 20–24).'),
  ('Anket seçeneklerinin \'karşılıklı dışlayıcı\' olması ne anlama gelir?', 'Her katılımcının yalnızca bir seçeneğe uyması', ['Seçeneklerin tümünün aynı uzunlukta olması', 'Her seçeneğin en az bir kişi tarafından seçilmesi', 'Seçeneklerin alfabetik sırayla dizilmesi'], 'Karşılıklı dışlayıcılık, seçeneklerin örtüşmemesi ve bir yanıtın yalnızca bir kategoriye girmesidir.'),
  ('Bir ankette yalnızca araba sahibi olanların yanıtlaması gereken sorulardan önce \'Arabanız var mı? Yoksa 12. soruya geçiniz\' ifadesi yer alıyor. Bu tür soruya ne ad verilir?', 'Filtre (yönlendirme) sorusu', ['Yüklü soru', 'Çift namlulu (birleşik) soru', 'Yönlendirici soru'], 'Filtre soruları, belirli bir alt bölüme yalnızca ilgili katılımcıların girmesini sağlar.'),
  ('Bir anketi asıl uygulamadan önce hedef kitleye benzeyen küçük bir gruba deneme amacıyla uygulamaya ne ad verilir?', 'Pilot uygulama', ['Panel uygulaması', 'Sayım', 'Delphi turu'], 'Pilot uygulama, soruların anlaşılırlığını, süreyi ve olası sorunları asıl veri toplamadan önce ortaya çıkarmak için yapılır.'),
  ('Okuma yazma oranı düşük bir kırsal bölgede hane anketi yapılacaktır. En uygun uygulama yolu hangisidir?', 'Yüz yüze, anketörlü uygulama', ['Posta yoluyla gönderilen ve katılımcının kendisinin dolduracağı anket', 'Yalnızca e-posta ile gönderilen çevrimiçi bağlantı', 'Sosyal medyada paylaşılan açık katılımlı form'], 'Anketör soruları sözlü olarak okuyup yanıtları kaydettiği için yüz yüze uygulama, okuma yazma bilmeyen katılımcıların da katılmasına olanak verir.'),
  ('Posta yoluyla yapılan anketlerin en bilinen zayıflığı aşağıdakilerden hangisidir?', 'Yanıt oranlarının genellikle düşük olması', ['Anketör etkisinin çok yüksek düzeyde olması', 'Görsel malzeme ya da yazılı açıklama kullanılamaması', 'Maliyetin yüz yüze uygulamadan her zaman yüksek olması'], 'Posta anketlerinde katılımcıyı teşvik edecek bir görüşmeci yoktur ve geri dönüş oranı çoğu zaman düşük kalır.'),
  ('Çevrimiçi anketlerin yüz yüze anketlere göre başlıca avantajı nedir?', 'Düşük maliyetle hızlı veri toplama', ['Tüm nüfus gruplarına eşit biçimde ulaşma', 'Anketörün belirsiz soruları açıklayabilmesi', 'Yanıt oranlarının her zaman en yüksek olması'], 'Çevrimiçi anketler basım, posta ve anketör maliyeti gerektirmez; ancak internet erişimi olmayanları dışarıda bırakabilir.'),
  ('Telefon anketlerinin yüz yüze anketlere kıyasla bir sınırlılığı aşağıdakilerden hangisidir?', 'Görsel kart ya da uzun seçenek listesi kullanmanın zor olması', ['Anketörün katılımcıyla hiçbir sözlü iletişim kuramaması', 'Geniş bir coğrafyaya ulaşmanın yüz yüze görüşmeden her zaman daha pahalı olması', 'Yanıtların kaydedilmesinin hiçbir şekilde mümkün olmaması'], 'Telefonda katılımcı seçenekleri yalnızca duyar; uzun listeler akılda tutulamaz ve görsel malzeme gösterilemez.'),
  ('Gözetimli anket uygulaması (ör. bir sınıfta anketin araştırmacı gözetiminde doldurulup toplanması) hangi avantajı sağlar?', 'Yanıt oranının yüksek olması ve soruların yerinde açıklanabilmesi', ['Katılımcıların ülke genelindeki tüm bölgelerden rastgele seçilmesi', 'Sosyal beğenirlik eğiliminin her durumda tamamen ortadan kalkması', 'Anketin hiçbir ön hazırlık ve pilot çalışma gerektirmemesi'], 'Toplu gözetimli uygulamada anketler aynı oturumda toplanır, bu da yanıt oranını artırır; anlaşılmayan noktalar da hemen açıklanabilir.'),
  ('Bir ankete 1.200 kişi davet edilmiş ve 300 kişi tam yanıt vermiştir. Yanıt oranı yüzde kaçtır?', '%25', ['%30', '%40', '%12,5'], 'Yanıt oranı = yanıt veren / davet edilen × 100 = 300/1.200 × 100 = %25.'),
  ('Yanıt oranını artırmak için yaygın olarak kullanılan yöntemlerden biri aşağıdakilerden hangisidir?', 'Yanıt vermeyenlere hatırlatma mesajı göndermek', ['Anketi mümkün olduğunca uzun ve ayrıntılı tutmak', 'Anketin amacını katılımcılardan tamamen gizlemek', 'Hassas soruları anketin en başına yerleştirmek'], 'Hatırlatmalar, kısa anket, anlaşılır amaç açıklaması ve küçük teşvikler yanıt oranını artırdığı bilinen yöntemlerdendir.'),
  ('Katılımcıların anketlerde kendilerini toplumca onaylanan biçimde gösterecek yanıtlar verme eğilimine ne ad verilir?', 'Sosyal beğenirlik eğilimi', ['Hawthorne etkisi', 'Merkezî eğilim (orta puan) hatası', 'Kapsam hatası'], 'Sosyal beğenirlik, kişilerin olumlu bir izlenim bırakmak için yanıtlarını toplumsal beklentilere göre ayarlamasıdır.'),
  ('Bir lisede yüz yüze yapılan ankette öğrencilere sınıf öğretmenlerinin yanında \'Hiç kopya çektiniz mi?\' diye soruluyor. Sonuçlar hakkında en olası değerlendirme hangisidir?', 'Kopya çekme oranı olduğundan düşük çıkabilir', ['Kopya çekme oranı olduğundan yüksek çıkabilir', 'Sonuçlar gerçek oranı tam olarak verir', 'Öğrencilerin çoğunluğu soruyu yanıtsız bırakır'], 'Hem soru hassastır hem de öğretmenin varlığı baskı yaratır; öğrenciler onaylanmayan davranışı az bildirme eğiliminde olur.'),
  ('Hassas konulardaki sorularda dürüst yanıt alma olasılığını artırmak için en uygun uygulama hangisidir?', 'Anketi adsız ve kendi kendine doldurulan biçimde uygulamak', ['Anketörün soruları yüksek sesle ve başkalarının yanında sorması', 'Katılımcıların adlarını ve okul numaralarını ankete yazdırmak', 'Soruları olumsuz davranışı açıkça kınayan ifadelerle yazmak'], 'Adsızlık ve görüşmeci olmadan doldurma, katılımcının yargılanma kaygısını azaltır ve sosyal beğenirliği düşürür.'),
  ('Bir araştırmacı 2015\'te bir ilin lise öğrencilerine tek seferlik bir anket uygulayarak o andaki okuma alışkanlıklarını betimliyor. Bu tasarım hangisidir?', 'Kesitsel anket', ['Panel (izleme) anketi', 'Kohort anketi', 'Trend anketi'], 'Kesitsel anket, verileri belirli bir zamanda tek seferde toplayarak o anın fotoğrafını çeker.'),
  ('Aynı kişilerin yıllar boyunca belirli aralıklarla tekrar tekrar ankete katıldığı tasarıma ne ad verilir?', 'Panel anketi', ['Trend anketi', 'Kesitsel anket', 'Kota anketi'], 'Panel anketlerinde aynı bireyler zaman içinde tekrar ölçülür; böylece bireysel değişim izlenebilir.'),
  ('Panel anketlerinin trend anketlerine göre sağladığı temel üstünlük nedir?', 'Aynı kişilerdeki bireysel değişimi izleyebilmesi', ['Katılımcı kaybı yaşanmaması ve tüm katılımcıların yıllarca araştırmada kalması', 'Her ölçümde yeni ve tamamen bağımsız örneklem seçilmesi', 'Maliyetinin her zaman tek seferlik kesitsel anketten düşük olması'], 'Panel tasarımı aynı kişileri izlediği için kimin nasıl değiştiğini gösterebilir; trend anketi yalnızca toplam düzeydeki değişimi gösterir.'),
  ('Panel anketlerinde katılımcıların zamanla araştırmadan ayrılmasına ne ad verilir?', 'Katılımcı kaybı', ['Kapsam hatası', 'Soru sırası (bağlam) etkisi', 'Hale etkisi'], 'Yıpranma, panel çalışmalarında taşınma, ilgisizlik ya da ölüm gibi nedenlerle katılımcıların ölçümler arasında kaybedilmesidir.'),
  ('Görüşme yönteminin anket yöntemine göre en belirgin avantajı aşağıdakilerden hangisidir?', 'Yanıtların ek sorularla derinleştirilebilmesi', ['Binlerce kişiye kısa sürede ve düşük maliyetle ulaşılabilmesi', 'Görüşmecinin katılımcıyı etkileme olasılığının bulunmaması', 'Verilerin her zaman doğrudan istatistiksel çözümlemeye uygun olması'], 'Görüşmeci, katılımcının yanıtına göre yeni sorular sorabilir ve belirsiz noktaları netleştirebilir.'),
  ('Görüşme yönteminin anket yöntemine göre bir dezavantajı aşağıdakilerden hangisidir?', 'Zaman ve maliyet gereksiniminin daha yüksek olması', ['Belirsiz soruların yerinde açıklanamaması', 'Okuma yazma bilmeyen kişilere uygulanamaması', 'Katılımcıların yanıtlarının ek sorularla derinleştirilememesi'], 'Her görüşme ayrı zaman, kayıt ve döküm gerektirdiği için görüşmeler anketlere göre pahalı ve yavaştır.'),
  ('Bir araştırmacı, deprem sonrası prefabrik konutlarda yaşayan ailelerin bu süreçte neler hissettiğini ve yaşamlarının nasıl değiştiğini anlamak istiyor. En uygun yöntem hangisidir?', 'Derinlemesine görüşme', ['Kapalı uçlu çevrimiçi anket', 'Yapılandırılmış sayım formu', 'Katılımsız trafik gözlemi'], 'Duygular ve yaşam deneyimleri gibi karmaşık konular, katılımcının kendi anlatımına alan tanıyan derinlemesine görüşmelerle anlaşılır.'),
  ('Görüşmecinin tüm katılımcılara aynı soruları aynı sırayla ve aynı sözcüklerle sorduğu, ek soru sormadığı görüşme türü hangisidir?', 'Yapılandırılmış görüşme', ['Yarı yapılandırılmış görüşme', 'Yapılandırılmamış görüşme', 'Odak grup görüşmesi'], 'Yapılandırılmış görüşme, sözlü olarak uygulanan bir ankete benzer; standart bir görüşme formuna sıkı sıkıya bağlı kalınır.'),
  ('Görüşmecinin önceden hazırlanmış bir soru listesini temel aldığı, ancak soruların sırasını değiştirebildiği ve gerektiğinde ek sorular sorabildiği görüşme türü hangisidir?', 'Yarı yapılandırılmış görüşme', ['Yapılandırılmış görüşme', 'Yapılandırılmamış (serbest) görüşme', 'Telefon anketi'], 'Yarı yapılandırılmış görüşme hem ortak bir çerçeve hem de esneklik sunar; bu nedenle eğitim ve sosyal bilimlerde çok kullanılır.'),
  ('Görüşmecinin yalnızca genel bir konu belirleyip soruları görüşmenin doğal akışı içinde oluşturduğu görüşme türü hangisidir?', 'Yapılandırılmamış görüşme', ['Yapılandırılmış görüşme', 'Standart anket görüşmesi', 'Telefonla yapılan kota anketi'], 'Yapılandırılmamış görüşmede hazır soru listesi yoktur; görüşme bir sohbet gibi katılımcının anlattıkları üzerinden ilerler.'),
  ('Yapılandırılmamış görüşme en çok hangi tür araştırma amacına uygundur?', 'Az bilinen bir deneyimi katılımcının kendi bakışından keşfetmeye', ['Büyük bir evrende belirli bir görüşün oranını kesin olarak hesaplamaya', 'Farklı illerdeki yanıtları standart ölçütlerle karşılaştırmaya', 'Önceden belirlenmiş seçeneklerin hangisinin daha sık seçildiğini saymaya'], 'Yapılandırılmamış görüşme esnek ve derin olduğundan keşfedici, anlamaya yönelik çalışmalara uygundur; oran tahmini ve standart karşılaştırma için uygun değildir.'),
  ('6–10 kişilik bir grubun bir moderatör eşliğinde belirli bir konuyu birlikte tartıştığı veri toplama yöntemine ne ad verilir?', 'Odak grup görüşmesi', ['Delphi tekniği', 'Panel anketi', 'Katılımsız doğal ortam gözlemi'], 'Odak grup, katılımcıların birbirlerinin görüşlerine tepki vererek etkileşim içinde tartıştığı grup görüşmesidir.'),
  ('Odak grup görüşmesinin bireysel görüşmelere göre özgün katkısı nedir?', 'Katılımcılar arasındaki etkileşimin yeni fikirler doğurması', ['Her katılımcının kişisel ve gizli konuları rahatça anlatabilmesi', 'Sonuçların doğrudan tüm evrene istatistiksel olarak genellenebilmesi', 'Moderatöre ve onun yönlendirme becerisine hiç gereksinim duyulmaması'], 'Odak gruplarda katılımcılar birbirinin söylediklerinden etkilenip tepki verir; bu etkileşim tek kişilik görüşmede ortaya çıkmayacak görüşleri açığa çıkarabilir.'),
  ('Bir odak grup görüşmesinde tek bir katılımcının sürekli konuşup diğerlerinin sessiz kaldığı görülüyor. Moderatörün en uygun davranışı hangisidir?', 'Diğer katılımcıları adlarıyla davet ederek söz dağılımını dengelemek', ['Konuşan katılımcıyı hemen gruptan çıkarıp görüşmeyi sonlandırmak', 'Durumu görmezden gelip baskın katılımcının konuşmasına izin vermek', 'Sessiz katılımcıları görüşme sonunda yazılı ankete yönlendirmek'], 'Moderatörün görevi tüm katılımcıların görüş bildirmesini sağlamaktır; baskın bir üye grup düşüncesine yol açabilir.'),
  ('Bir görüşmede katılımcı \'O dönem çok zordu\' dediğinde görüşmecinin \'Zor derken neyi kastediyorsunuz, bir örnek verebilir misiniz?\' diye sorması hangi tekniğe örnektir?', 'Sondaj (derinleştirme) sorusu', ['Filtre sorusu', 'Yönlendirici soru', 'Kapalı uçlu seçenekli soru'], 'Sondaj soruları, katılımcının yanıtını açmasını, örneklendirmesini ya da netleştirmesini isteyen ek sorulardır.'),
  ('Görüşmecinin katılımcının söylediklerini kısaca kendi sözcükleriyle özetleyip \'Doğru mu anladım?\' diye sorması hangi amaca yöneliktir?', 'Görüşmecinin anlayışını katılımcıyla doğrulamak', ['Katılımcıyı farklı bir görüşe geçmeye ikna etmek ve görüşünü değiştirmek', 'Görüşmenin süresini uzatarak daha çok ücret almak', 'Katılımcının kimlik bilgilerini doğrulayıp kayda geçirmek'], 'Yansıtma ve özetleme, yanlış anlamaları görüşme sırasında düzeltme olanağı verir ve katılımcıya dinlendiğini hissettirir.'),
  ('Bir görüşmenin başında görüşmecinin kendini tanıtması, araştırmanın amacını anlatması ve katılımcıyla kısa bir sohbet etmesi hangi amaca hizmet eder?', 'Güven ilişkisi (yakınlık) kurmak', ['Örneklem büyüklüğünü artırmak', 'Katılımcının yanıtlarını önceden belirlemek', 'Görüşmeyi yapılandırılmış hâle getirmek'], 'Görüşmenin başında kurulan yakınlık, katılımcının rahatlamasını ve daha açık konuşmasını sağlar.'),
  ('Görüşmecinin yaşı, cinsiyeti, giyimi ya da etnik kökeni gibi özelliklerinin katılımcının yanıtlarını etkilemesine ne ad verilir?', 'Görüşmeci etkisi', ['Kapsam hatası', 'Örnekleme (seçim) hatası', 'Onaylama eğilimi'], 'Görüşmeci etkisi, görüşmecinin kişisel özelliklerinin ya da davranışının yanıtları sistematik olarak değiştirmesidir.'),
  ('Bir görüşme için ortam seçilirken öncelikle hangi ölçüt dikkate alınmalıdır?', 'Katılımcının rahat edebileceği, sessiz ve mahremiyeti koruyan bir yer olması', ['Görüşmecinin evine ya da iş yerine en yakın, ulaşımı en kolay ve en ucuz yer olması', 'Ortamda başka kişilerin de bulunup konuşmayı dinleyebilmesi', 'Görüşmenin gürültülü olsa da olabildiğince kısa sürede bitirilmesi'], 'Sessiz ve mahremiyetin korunduğu bir ortam hem kayıt kalitesini hem de katılımcının açık konuşmasını destekler.'),
  ('Görüşmelerin ses kaydına alınmasının yalnızca not almaya göre başlıca avantajı nedir?', 'Katılımcının sözlerinin eksiksiz ve aynen saklanması', ['Katılımcının kayıt cihazından hiç etkilenmemesi ve doğal davranması', 'Katılımcının onamını almanın gereksiz hâle gelmesi', 'Dökümü yapmaya ve çözümlemeye gerek kalmaması'], 'Ses kaydı, görüşmecinin belleğine ya da hızlı notlarına bağımlılığı ortadan kaldırarak yanıtların aynen korunmasını sağlar. Kayıt için onam gerekir.'),
  ('Ses kaydına alınan görüşmelerin kelimesi kelimesine yazıya geçirilmesine ne ad verilir?', 'Transkripsiyon', ['Kodlama', 'Pilot (deneme) uygulaması', 'Tabakalama'], 'Transkripsiyon, sözlü verinin yazılı metne dönüştürülmesidir ve nitel çözümlemenin ilk adımlarındandır.'),
  ('Bir görüşme protokolünde (rehberinde) genellikle aşağıdakilerden hangisi yer almaz?', 'Katılımcıların vermesi gereken doğru yanıtlar', ['Görüşmenin amacını açıklayan giriş metni', 'Ana sorular ve olası sondaj soruları', 'Onam ve gizlilikle ilgili bilgilendirme'], 'Görüşme protokolü giriş, onam, ana sorular, sondajlar ve kapanışı içerir; görüşmelerde \'doğru yanıt\' yoktur, amaç katılımcının bakışını öğrenmektir.'),
  ('Görüşmenin sonunda \'Eklemek istediğiniz başka bir şey var mı?\' sorusunun sorulmasının amacı nedir?', 'Katılımcının önemli bulduğu ama sorulmamış konuları dile getirmesine fırsat vermek', ['Görüşmeyi uzatarak katılımcıyı yormak', 'Katılımcının önceki tüm yanıtlarını geri almasını sağlamak', 'Görüşmenin yapılandırılmış olduğunu kanıtlamak'], 'Kapanış sorusu, görüşmecinin aklına gelmeyen ama katılımcı için önemli olan bilgilerin kaybolmamasını sağlar.'),
  ('Sıradan insanların yaşadıkları tarihsel olayları kendi anlatımlarıyla kayda geçirmeyi amaçlayan görüşme yaklaşımına ne ad verilir?', 'Sözlü tarih', ['Delphi tekniği', 'Odak grup tartışması', 'Yapılandırılmış telefon anketi'], 'Sözlü tarih, tanıkların anılarını görüşmelerle kaydederek yazılı kaynaklarda yer almayan deneyimleri belgeleyen bir yöntemdir.'),
  ('1960\'larda Almanya\'ya işçi olarak giden kişilerin göç deneyimini incelemek isteyen bir araştırmacı için en uygun yaklaşım hangisidir?', 'Yaşayan tanıklarla sözlü tarih görüşmeleri', ['Bugünkü Alman nüfusuna kapalı uçlu çevrimiçi anket', 'Göçmenlerin torunlarının okullarında katılımsız gözlem', 'Rastgele seçilmiş hanelerde kısa telefon anketi'], 'Geçmiş deneyimi en iyi anlatacak kişiler o süreci yaşamış tanıklardır; sözlü tarih görüşmeleri bu kişisel anlatıları kayda geçirir.'),
  ('Bir kişinin doğumundan bugüne kadar yaşamını, dönüm noktalarıyla birlikte kendi anlatımıyla ortaya koyduğu görüşme türüne ne ad verilir?', 'Yaşam öyküsü görüşmesi', ['Kesitsel anket uygulaması', 'Yapılandırılmış gözlem', 'Kota örneklemesi uygulaması'], 'Yaşam öyküsü görüşmeleri, bireyin yaşamını bütün olarak ve kendi bakışıyla anlatmasını sağlar.'),
  ('Araştırmacının sonuçlarını genellemek istediği bireylerin ya da birimlerin tümüne ne ad verilir?', 'Evren', ['Örneklem', 'Örneklem çerçevesi', 'Tabaka'], 'Evren (popülasyon), araştırma sorusunun ilgilendiği bütün birimlerdir; örneklem bu evrenden seçilen alt kümedir.'),
  ('Bir araştırmacı Türkiye\'deki tüm lise son sınıf öğrencilerinin sınav kaygısını incelemek istiyor ve 40 okuldan 2.000 öğrenciye ulaşıyor. Bu çalışmada 2.000 öğrenci neyi oluşturur?', 'Örneklemi', ['Evreni', 'Tabakayı', 'Örneklem çerçevesini'], '2.000 öğrenci, genelleme yapılmak istenen evrenden (tüm lise son sınıf öğrencileri) seçilen örneklemdir.'),
  ('Evrendeki tüm birimlerden veri toplanmasına ne ad verilir?', 'Tam sayım', ['Basit rastgele örnekleme', 'Pilot uygulama', 'Küme örneklemesi'], 'Sayımda evrenin her birimi incelenir; nüfus sayımları bunun bilinen örneğidir.'),
  ('Örneklemle çalışmanın sayıma göre başlıca nedeni aşağıdakilerden hangisidir?', 'Zaman, maliyet ve emek tasarrufu sağlaması', ['Örneklemin evrenden her zaman daha doğru sonuç vermesi', 'Örnekleme hatasının sayımda daha yüksek ve daha belirsiz olması', 'Örneklemle istatistiksel hesap yapmanın gereksiz ve imkânsız olması'], 'Büyük evrenlerin tamamına ulaşmak çok pahalı ve uzun sürer; iyi seçilmiş bir örneklem makul bir kesinlikle evren hakkında bilgi verir.'),
  ('Örneklemin seçildiği, evrendeki birimlerin listesine ne ad verilir?', 'Örneklem çerçevesi', ['Örneklem büyüklüğü', 'Tabaka', 'Güven aralığı'], 'Örneklem çerçevesi, örneklemin çekileceği liste ya da kaynaktır (ör. okul kayıt listesi, seçmen kütüğü).'),
  ('Bir ilçedeki hanelerin görüşünü öğrenmek isteyen bir araştırmacı, örneklemini yalnızca sabit hat telefonu rehberinden seçiyor. Bu durum hangi tür hataya yol açar?', 'Kapsam hatası', ['Ölçme hatası', 'Görüşmeci etkisi', 'Gözlemciler arası uyumsuzluk'], 'Sabit hattı olmayan haneler örneklem çerçevesinde yer almadığı için hiçbir şekilde örnekleme giremez; bu kapsam hatasıdır.'),
  ('Evrendeki her bireyin örnekleme seçilme olasılığının eşit olduğu ve seçimin kura ya da rastgele sayılarla yapıldığı örnekleme yöntemi hangisidir?', 'Basit rastgele örnekleme', ['Kota örneklemesi', 'Kartopu örneklemesi', 'Amaçlı (yargısal) örnekleme'], 'Basit rastgele örneklemede her birim eşit olasılıkla ve birbirinden bağımsız olarak seçilir.'),
  ('Bir öğretmen 32 kişilik sınıfından 8 öğrenciyi seçmek için tüm adları kâğıtlara yazıp bir torbaya koyuyor ve karıştırıp 8 kâğıt çekiyor. Bu hangi örnekleme yöntemidir?', 'Basit rastgele örnekleme', ['Sistematik örnekleme', 'Tabakalı örnekleme', 'Kolay ulaşılabilir örnekleme'], 'Torbadan kura çekmek her öğrenciye eşit seçilme şansı veren basit rastgele örneklemenin klasik bir uygulamasıdır.'),
  ('Basit rastgele örneklemenin uygulanabilmesi için öncelikle neye gereksinim vardır?', 'Evrendeki tüm birimlerin eksiksiz bir listesine', ['Evrenin önceden alt gruplara ayrılmış ve etiketlenmiş olmasına', 'Katılımcıların kendi istekleriyle başvurmalarına ve gönüllü olmalarına', 'İlk katılımcıların diğerlerini önermesine'], 'Her birime eşit şans tanımak için evrendeki tüm birimlerin bilinmesi, yani bir örneklem çerçevesinin bulunması gerekir.'),
  ('Bir listedeki birimlerden rastgele bir başlangıç noktası seçilip ardından her k\'ıncı birimin örnekleme alındığı yöntem hangisidir?', 'Sistematik örnekleme', ['Basit rastgele örnekleme', 'Küme örneklemesi', 'Kartopu (zincir) örneklemesi'], 'Sistematik örneklemede rastgele bir başlangıçtan sonra sabit aralıklarla (her k\'ıncı) birim seçilir.'),
  ('5.000 kişilik bir kayıt listesinden sistematik örneklemeyle 250 kişi seçilecektir. Örnekleme aralığı (k) kaç olmalıdır?', '20', ['25', '50', '10'], 'k = N / n = 5.000 / 250 = 20; yani rastgele bir başlangıçtan sonra her 20. kişi seçilir.'),
  ('Bir fabrikada üretim bandından çıkan her 50. ürünün kalite kontrolüne alınması hangi örnekleme yöntemine örnektir?', 'Sistematik örnekleme', ['Basit rastgele (kura ile) örnekleme', 'Kota örneklemesi', 'Amaçlı örnekleme'], 'Sabit aralıklarla (her 50. ürün) seçim yapılması sistematik örneklemenin tanımına uyar.'),
  ('Evrenin önce yaş, bölge ya da cinsiyet gibi bir özelliğe göre homojen alt gruplara ayrıldığı ve her alt gruptan rastgele seçim yapıldığı örnekleme yöntemi hangisidir?', 'Tabakalı örnekleme', ['Küme örneklemesi', 'Kota örneklemesi', 'Sistematik örnekleme'], 'Tabakalı örneklemede evren kendi içinde benzer tabakalara ayrılır ve her tabakadan olasılıklı (rastgele) seçim yapılır.'),
  ('Bir üniversitede öğrencilerin %70\'i kadın, %30\'u erkektir. 400 kişilik orantılı tabakalı örneklemde kaç erkek öğrenci yer almalıdır?', '120', ['280', '200', '130'], 'Erkeklerin payı %30 olduğundan 400 × 0,30 = 120 erkek öğrenci seçilir.'),
  ('Tabakalı örneklemenin basit rastgele örneklemeye göre en önemli üstünlüğü nedir?', 'Önemli alt grupların örneklemde yeterince temsil edilmesini güvenceye alması', ['Evrendeki birimlerin listesine hiç gereksinim duymaması', 'Araştırmacının katılımcıları kendi kişisel yargısıyla seçebilmesi', 'Seçimi hızlandırmak için yalnızca gönüllülerin alınması'], 'Tabakalama, şansa bağlı olarak bazı grupların az temsil edilmesini önler ve tahminlerin kesinliğini artırabilir.'),
  ('Evrenin doğal gruplara (okullar, mahalleler, köyler gibi) ayrıldığı, bu gruplardan bazılarının rastgele seçildiği ve seçilen gruplardaki tüm birimlerin incelendiği yöntem hangisidir?', 'Küme örneklemesi', ['Tabakalı örnekleme', 'Sistematik örnekleme', 'Kota örneklemesi'], 'Küme örneklemesinde seçim birimi bireyler değil gruplardır; seçilen kümelerin tamamı ya da bir kısmı incelenir.'),
  ('Bir ilin 120 ilkokulundan 10 okul rastgele seçiliyor ve bu 10 okuldaki tüm dördüncü sınıf öğrencilerine okuma testi uygulanıyor. Bu hangi örnekleme yöntemidir?', 'Küme örneklemesi', ['Tabakalı örnekleme', 'Basit rastgele örnekleme', 'Kolay ulaşılabilir örnekleme'], 'Rastgele seçilen birimler okullar (kümeler) olduğu ve seçilen okullardaki tüm öğrenciler incelendiği için bu küme örneklemesidir.'),
  ('Bir araştırmacı alışveriş merkezinin girişinde durup yanından geçen ve durmayı kabul eden ilk 100 kişiye anket uyguluyor. Bu örnekleme yöntemi hangisidir?', 'Kolay ulaşılabilir örnekleme', ['Basit rastgele (olasılıklı) örnekleme', 'Sistematik örnekleme', 'Tabakalı örnekleme'], 'Araştırmacı kolayca ulaşabildiği ve hazırda bulunan kişileri seçtiği için bu kolay ulaşılabilir (uygun) örneklemedir.'),
  ('Bir psikoloji öğretmeninin kendi derslerindeki öğrencilere anket uygulayıp sonuçları \'Türk gençleri\' hakkında genellemesinin temel sorunu nedir?', 'Örneklem evreni temsil etmeyebilir', ['Örneklem gereğinden fazla büyüktür', 'Anket soruları açık uçlu sorulmuştur', 'Öğrencilerin onamı alınmıştır'], 'Kolay ulaşılabilir örneklem belirli bir okul ve sınıfla sınırlıdır; bu öğrenciler tüm Türk gençlerinin özelliklerini yansıtmayabilir.'),
  ('Bir televizyon programının izleyicilerden \'Görüşünüzü bildirmek için mesaj atın\' diye istemesiyle toplanan oylar hangi tür örneklem oluşturur?', 'Gönüllü yanıt örneklemi', ['Basit rastgele (olasılıklı) örneklem', 'Tabakalı örneklem', 'Sistematik örneklem'], 'Katılımcılar kendileri katılmaya karar verdiği için bu gönüllü (kendiliğinden seçilmiş) bir örneklemdir.'),
  ('Gönüllü yanıt örneklemlerinin en önemli sorunu aşağıdakilerden hangisidir?', 'Konu hakkında güçlü görüşleri olanların aşırı temsil edilmesi', ['Katılımcı sayısının her zaman ve her koşulda çok düşük kalması', 'Yanıtların sayısal biçimde özetlenmesinin hiçbir zaman mümkün olmaması', 'Örneklem çerçevesinin gereğinden fazla güncel ve eksiksiz olması'], 'Katılmaya karar verenler çoğunlukla konuyla yakından ilgilenen ya da güçlü bir görüşü olanlardır; bu da sonuçları bir yöne kaydırır.'),
  ('Evsizler ya da madde bağımlıları gibi listesi bulunmayan ve ulaşılması zor gruplarla yapılan araştırmalarda, ilk katılımcıların tanıdıkları başka kişileri önermesiyle örneklemin büyütüldüğü yöntem hangisidir?', 'Kartopu örneklemesi', ['Sistematik örnekleme', 'Küme örneklemesi', 'Basit rastgele örnekleme'], 'Kartopu örneklemesinde her katılımcı yeni katılımcılara ulaşmayı sağlar; örneklem bir kartopu gibi büyür.'),
  ('Araştırmacının, araştırma amacına en uygun bilgiyi sağlayacağını düşündüğü kişileri bilinçli olarak seçtiği örnekleme yaklaşımına genel olarak ne ad verilir?', 'Amaçlı örnekleme', ['Basit rastgele örnekleme', 'Sistematik örnekleme', 'Gönüllü yanıt örneklemesi'], 'Amaçlı (yargısal) örneklemede seçim, araştırmacının belirlediği ölçütlere ve bilgi zengini durumlara göre yapılır.'),
  ('Bir anket şirketinin 400 kişilik kota örnekleminde 18–29 yaş grubunun %25 olması isteniyor. Bu yaş grubunun kotası kaç kişidir?', '100', ['25', '75', '125'], '400 × 0,25 = 100 kişi.'),
  ('Aşağıdaki örnekleme yöntemlerinden hangisi olasılıklı bir yöntemdir?', 'Küme örneklemesi', ['Kota örneklemesi', 'Kartopu örneklemesi', 'Kolay ulaşılabilir örnekleme'], 'Küme örneklemesinde kümeler rastgele seçilir; diğer üç yöntemde seçim olasılıkları bilinmez.'),
  ('Örneklemden hesaplanan bir değer ile evrenin gerçek değeri arasında, yalnızca evrenin tamamı yerine bir parçası incelendiği için ortaya çıkan farka ne ad verilir?', 'Örnekleme hatası', ['Kapsam (çerçeve) hatası', 'Ölçme hatası', 'Görüşmeci etkisi'], 'Örnekleme hatası, şansa bağlı olarak örneklemin evrenden biraz farklı çıkmasıdır; olasılıklı örneklemede hesaplanabilir.'),
  ('Örnekleme hatasıyla ilgili aşağıdaki ifadelerden hangisi doğrudur?', 'Örneklem büyüdükçe örnekleme hatası genellikle küçülür', ['Örneklem büyüdükçe örnekleme hatası her zaman büyür', 'Tam sayımda örnekleme hatası en yüksek düzeydedir', 'Örnekleme hatası yalnızca kartopu örneklemesinde görülür'], 'Daha büyük rastgele örneklemler evreni daha yakından yansıtır; tam sayımda örnekleme hatası yoktur.'),
  ('Diğer koşullar aynıyken güven düzeyi %95\'ten %99\'a yükseltilirse hata payı nasıl değişir?', 'Büyür', ['Küçülür', 'Değişmez', 'Sıfıra iner'], 'Daha yüksek güven için daha geniş bir aralık gerekir; bu nedenle hata payı büyür.'),
  ('Bir araştırmacının gerekli örneklem büyüklüğünü belirlerken dikkate alması gereken etkenlerden biri aşağıdakilerden hangisi değildir?', 'Görüşmecilerin göz rengi', ['İstenen hata payı', 'Seçilen güven düzeyi', 'Evrendeki değişkenliğin büyüklüğü'], 'Örneklem büyüklüğü; istenen kesinlik, güven düzeyi, evrendeki değişkenlik ve beklenen yanıt oranı gibi etkenlere bağlıdır.'),
  ('Bir araştırmacı 400 tam yanıta ihtiyaç duyuyor ve beklenen yanıt oranının %50 olduğunu biliyor. En az kaç kişiye anket gönderilmelidir?', '800', ['400', '600', '200'], 'Gönderilecek sayı = gereken yanıt / yanıt oranı = 400 / 0,50 = 800.'),
  ('Bir örneklemin \'temsil edici\' olması ne anlama gelir?', 'İlgilenilen özellikler bakımından evrenin küçük bir kopyası gibi olması', ['Katılımcılarının tamamının aynı özelliklere sahip olması', 'Örneklem büyüklüğünün en az evrenin yarısı kadar ya da daha fazla olması', 'Katılımcıların araştırmacı tarafından tek tek seçilmesi'], 'Temsil edici bir örneklem, araştırma için önemli özelliklerde evrenle benzer dağılımlar gösterir; bu da sonuçların evrene genellenmesine olanak verir.'),
  ('Bir araştırmacı spor salonuna gelen kişilerle anket yaparak \'Türkiye\'de yetişkinlerin %70\'i haftada üç kez spor yapıyor\' sonucuna varıyor. Bu sonuçtaki temel sorun nedir?', 'Örneklem, spor yapma olasılığı yüksek kişilerden seçilmiştir', ['Örneklem büyüklüğü hesaplanırken güven düzeyi yanlış alınmıştır', 'Anket soruları açık uçlu olarak yazıldığı için kodlanamamıştır', 'Spor salonu üyelerinin onamı alınmadan anket uygulanmıştır'], 'Spor salonunda bulunanlar zaten spor yapan kişilerdir; bu seçim yanlılığı sonucu evrenin gerçek oranından çok yukarı taşır.'),
  ('Bir anket şirketi yalnızca sabah 10.00 ile 12.00 arasında evlere giderek görüşme yapıyor. Bu uygulama örnekleme hangi grupları daha az alacaktır?', 'O saatlerde evde olmayan çalışan kişileri', ['Emekli ve ev hanımı olarak çalışan kişileri', 'Evden çalışan ve gündüz evde bulunan kişileri', 'Okul öncesi çocuğu olan ve evde kalan ebeveynleri'], 'Mesai saatlerinde evde olmayan çalışanlara ulaşılamaz; örneklem gündüz evde bulunanlara doğru kayar. Bu yüzden ziyaretler farklı saatlere yayılır ve tekrar edilir.'),
  ('Katılımcıların araştırmanın amacı, süreci, olası riskleri ve istedikleri zaman ayrılabilecekleri konusunda bilgilendirildikten sonra katılmayı kabul etmelerine ne ad verilir?', 'Bilgilendirilmiş onam', ['Katılımcı teyidi', 'Veri doygunluğu', 'Pilot uygulama'], 'Bilgilendirilmiş onam, katılımcının araştırma hakkında yeterli bilgiye sahip olarak ve gönüllü biçimde katılmayı kabul etmesidir.'),
  ('18 yaşından küçük öğrencilerle okulda yapılacak bir anket çalışmasında genellikle kimden onam alınması gerekir?', 'Hem velilerden hem de öğrencilerin kendisinden', ['Yalnızca okul müdüründen ve sınıf öğretmeninden', 'Yalnızca anketi uygulayacak görüşmecilerden', 'Hiç kimseden, çünkü anket zararsızdır'], 'Reşit olmayanlar için yasal temsilci (veli) izni gerekir; çocuğun kendi rızası (assent) da alınmalıdır. Okul izni ayrıca gerekebilir ama tek başına yeterli değildir.'),
  ('Bir araştırma raporunda katılımcıların adları yerine \'Ö1, Ö2\' gibi kodlar kullanılmasının amacı nedir?', 'Katılımcıların kimliklerini korumak', ['Raporun sayfa sayısını ve uzunluğunu azaltmak', 'Katılımcıların yaşlarını ve cinsiyetlerini belirtmek', 'Görüşmelerin hangi sırayla yapıldığını gizlemek'], 'Kod adları (takma adlar) katılımcıların raporda tanınmasını önleyerek gizliliği korur.'),
  ('Bir katılımcı görüşmenin ortasında devam etmek istemediğini söylüyor. Araştırmacının etik açıdan doğru davranışı hangisidir?', 'Görüşmeyi sonlandırıp kararına saygı göstermek', ['Katılımcıyı ikna edip görüşmeyi tamamlamasını sağlamak', 'Görüşmeyi kaydı kapatmadan gizlice sürdürmek', 'Katılımcının onam formunu imzaladığını hatırlatıp devam etmek'], 'Gönüllülük ilkesi gereği katılımcı araştırmanın herhangi bir aşamasında hiçbir yaptırımla karşılaşmadan ayrılabilir.'),
  ('Araştırma sırasında toplanan kimlik bilgisi içeren ses kayıtlarının nasıl saklanması gerekir?', 'Yetkisiz kişilerin erişemeyeceği güvenli bir ortamda', ['Herkesin erişebileceği açık bir paylaşım klasöründe', 'Katılımcıların komşularına ve yakınlarına dağıtılarak', 'Araştırma bittikten sonra sosyal medyada yayımlanarak'], 'Kişisel veriler, gizlilik taahhüdünü korumak için şifreli ya da kilitli ortamlarda saklanmalı ve yalnızca yetkili kişilerce erişilmelidir.'),
  ('Araştırma etik kurullarının temel görevi aşağıdakilerden hangisidir?', 'Araştırmanın katılımcılara yönelik risklerini ve haklarını değerlendirmek', ['Araştırma sonuçlarının hangi yönde çıkacağını önceden belirlemek', 'Araştırmacıların bilimsel yayınlarını dergiler adına okuyup düzeltmek ve onaylamak', 'Örneklem büyüklüğünü her araştırma için aynı sayıya sabitlemek'], 'Etik kurullar, katılımcıların korunup korunmadığını, onam süreçlerini ve olası zararları araştırma başlamadan önce inceler.'),
  ('Bir anketin giriş metninde aşağıdaki bilgilerden hangisinin bulunması gerekli değildir?', 'Araştırmacının hangi takımı tuttuğu', ['Araştırmanın amacı', 'Yanıtların nasıl kullanılacağı ve kimlerle paylaşılacağı', 'Katılımın gönüllü olduğu'], 'Giriş (kapak) metni; amaç, gönüllülük, gizlilik, yaklaşık süre ve iletişim bilgisi gibi katılımcının karar vermesi için gereken bilgileri içerir.'),
  ('Bir araştırma sorusunu incelemek için birden fazla veri toplama yönteminin (ör. gözlem, görüşme ve anket) birlikte kullanılmasına ne ad verilir?', 'Yöntem üçgenlemesi', ['Kartopu örneklemesi', 'Veri doygunluğu', 'Sistematik örnekleme'], 'Yöntem üçgenlemesi, farklı yöntemlerin birbirinin zayıflığını dengelemesi ve bulguların farklı kaynaklardan doğrulanması amacıyla yapılır.'),
  ('Bir araştırmacı çocukların oyun parkındaki cinsiyete göre oyun tercihlerini incelemek istiyor. 4–5 yaşındaki çocuklarla anket yapmanın uygun olmamasının temel nedeni nedir?', 'Bu yaştaki çocuklar yazılı soruları okuyup yanıtlayamaz', ['Çocukların oyun parkında hiç oyun oynamaması', 'Gözlemin çocuklar üzerinde yasal olarak yasak olması', 'Çocukların oyun tercihlerinin yaşla birlikte hiçbir zaman değişmemesi'], 'Okuma yazma bilmeyen küçük çocuklarda gözlem ya da uygun görsel/sözlü teknikler kullanılır; yazılı anket uygun değildir.'),
  ('Bir belediye bir meydanın yayalarca nasıl kullanıldığını (hangi saatlerde kalabalık, hangi alanlar boş) öğrenmek istiyor. En uygun yöntem hangisidir?', 'Farklı saatlerde sistematik gözlem', ['Meydanı kullanan rastgele kişilerle derinlemesine görüşme', 'Kent sakinlerine posta anketi', 'Uzmanlarla Delphi çalışması'], 'Mekân kullanımı doğrudan gözlenebilen bir davranıştır; farklı saat ve günlere yayılmış gözlem yoğunluk örüntüsünü en doğru biçimde gösterir.'),
  ('Bir araştırmacının yeni veri toplamak yerine daha önce başka bir kurum tarafından toplanmış verileri (ör. nüfus sayımı sonuçları) kendi sorusu için çözümlemesine ne ad verilir?', 'İkincil veri çözümlemesi', ['Birincil (özgün) veri toplama', 'Katılımlı gözlem', 'Pilot uygulama'], 'İkincil veri, araştırmacının kendisinin toplamadığı, başka amaçlarla toplanmış veridir; zaman ve maliyet tasarrufu sağlar.'),
  ('Bir araştırmacı 1930\'lu yıllarda köy okullarındaki eğitim uygulamalarını incelemek için o dönemin okul defterlerini, resmî yazışmaları ve öğretmen raporlarını inceliyor. Bu veri toplama yöntemi hangisidir?', 'Doküman incelemesi', ['Katılımlı gözlem', 'Yapılandırılmış görüşme', 'Kota örneklemesi'], 'Yazılı belgelerin sistematik olarak incelenmesi doküman incelemesidir; tanıklara ulaşılamayan geçmiş dönemler için özellikle değerlidir.'),
  ('Doküman incelemesinin gözlem ve görüşmeye göre bir üstünlüğü aşağıdakilerden hangisidir?', 'Belgelerin araştırmacının varlığından etkilenmemesi', ['Belgelerin her zaman eksiksiz ve yansız olması', 'Belgelerin araştırma sorusuna göre üretilmiş olması', 'Belgelerin katılımcıların duygularını doğrudan ölçmesi'], 'Belgeler araştırmadan önce ve araştırmacıdan bağımsız üretildiği için tepkisel değildir; gözlemci ya da görüşmeci etkisi taşımaz. Yine de eksik ya da yanlı olabilirler.'),
  ('Bir okul rehber öğretmeni devamsızlık nedenlerini araştırırken önce okulun e-okul devamsızlık kayıtlarını çözümlüyor. Bu kayıtlar için aşağıdakilerden hangisi söylenebilir?', 'Kurum kayıtlarına dayalı ikincil veridir', ['Katılımlı gözlemle toplanmış birincil veridir', 'Odak grup görüşmesinden elde edilmiş veridir', 'Gönüllü yanıt örnekleminden elde edilmiş anket verisidir'], 'Devamsızlık kayıtları yönetsel amaçla zaten tutulmaktadır; araştırma için yeniden kullanıldıklarında ikincil veri olurlar.'),
  ('Bir gözlem formunda \'öğrenci soru sorar\' davranışı için \'parmak kaldırıp söz alarak öğretmene ders konusuyla ilgili soru yöneltmesi\' gibi ayrıntılı bir tanım yapılmasının amacı nedir?', 'Farklı gözlemcilerin davranışı aynı biçimde kodlamasını sağlamak', ['Formun daha uzun, ayrıntılı ve resmî bir belge gibi görünmesini sağlamak', 'Öğrencilerin soru sormasını yasaklamak', 'Gözlemciyi davranışı yorumlamaya teşvik etmek'], 'İşlevsel (operasyonel) tanımlar, neyin kodlanıp neyin kodlanmayacağını belirginleştirir ve gözlemciler arası uyumu artırır.'),
  ('Gözlem araştırmalarında \'pilot gözlem\' yapılmasının temel amacı nedir?', 'Gözlem formunun ve kategorilerin uygulamada işleyip işlemediğini görmek', ['Asıl gözlem verilerinin yerine geçecek kesin ve son sonuçlar elde etmek', 'Katılımcıların onamını gözlem sonrasına ertelemek ve hiçbir zaman almamak', 'Gözlemcinin hiç eğitim almadan doğrudan sahaya çıkmasını sağlamak'], 'Pilot gözlem, kategorilerin eksik, örtüşen ya da gözlenemez olup olmadığını ve gözlemcinin hızının yeterli olup olmadığını ortaya koyar.'),
  ('Gözlem yönteminin genel sınırlılıklarından biri aşağıdakilerden hangisidir?', 'Geçmişte olmuş olayların doğrudan incelenememesi', ['Davranışın gerçekleştiği anda kaydedilebilmesi', 'Söylenen ile yapılanın karşılaştırılabilmesi', 'Katılımcılardan sözel ifade ya da okuma yazma becerisi beklenmemesi'], 'Gözlem yalnızca gözlem anında gerçekleşen davranışı yakalar; geçmiş olaylar için belgeler ya da görüşmeler gerekir. Diğer seçenekler gözlemin üstünlükleridir.'),
  ('Bir araştırmacının bir okulun öğretmenler odasında bir dönem boyunca sohbetlere katılıp kendi araştırmacı kimliğini açıkça belirterek çalışması hangi gözlem biçimine en iyi uyar?', 'Açık katılımlı gözlem', ['Gizli katılımsız gözlem', 'Kontrollü laboratuvar gözlemi', 'Gizli tam katılımcı gözlem'], 'Araştırmacı ortamın etkinliklerine katıldığı ve kimliğini açıkça belirttiği için bu açık katılımlı gözlemdir.'),
  ('\'Belediyenin geri dönüşüm programını biliyor ve destekliyor musunuz?\' sorusunun içerdiği kusur aşağıdakilerden hangisidir?', 'Bilmek ve desteklemek ayrı ayrı sorulmalıdır', ['Soru yalnızca kapalı uçlu sorulabilecek bir konudadır', 'Sorunun tek bir konuyu sorması yetersizdir', 'Soru katılımcıyı programı eleştirmeye yönlendirir'], 'Programı bilen ama desteklemeyen ya da bilmeden destekleyen kişiler tek bir evet/hayır ile yanıt veremez; bu bir çift namlulu sorudur.'),
  ('Bir anketin kapak yazısında \'Bu anket yaklaşık 10 dakika sürmektedir\' bilgisinin verilmesinin amacı nedir?', 'Katılımcının katılıp katılmamaya bilgiyle karar vermesini sağlamak', ['Katılımcının anketi bitirmeden ayrılmasını yasaklamak ve engellemek', 'Anketin gerçek süresini katılımcılardan gizlemek ve kısa göstermek', 'Örneklem büyüklüğünü hesaplamaya yardımcı olmak'], 'Süre bilgisi hem bilgilendirilmiş onamın bir parçasıdır hem de beklentiyi belirleyerek yarıda bırakmayı azaltabilir.'),
  ('Bir ankette kişisel bilgilerin (yaş, cinsiyet, sınıf) toplandığı soru grubuna ne ad verilir?', 'Demografik sorular', ['Sondaj (derinleştirme) soruları', 'Filtre soruları', 'Yüklü sorular'], 'Demografik sorular katılımcıların arka plan özelliklerini toplar ve sonuçların alt gruplara göre karşılaştırılmasını sağlar.'),
  ('Bir ankette \'Hangi spor dalıyla ilgileniyorsunuz? (Futbol / Basketbol / Voleybol)\' sorusunun düzeltilmesi için aşağıdakilerden hangisi en uygundur?', '\'Diğer\' ve \'Sporla ilgilenmiyorum\' gibi seçenekler eklemek', ['Seçenekleri yalnızca futbolla sınırlayıp tek seçenek bırakmak', 'Soruyu iki ayrı konuyu soran tek bir cümleye dönüştürmek', 'Soruyu \'Neden futbolu tercih ediyorsunuz?\' biçiminde yönlendirici hâle getirmek'], 'Liste kapsayıcı değildir; başka sporlarla ilgilenenler ve sporla ilgilenmeyenler için seçenek eklenmelidir.'),
  ('Bir öğrenci anketinde \'Ders çalışma süreniz günde ortalama kaçtır?\' sorusunun seçenekleri \'0–1 saat\', \'1–2 saat\', \'2–3 saat\', \'3 saatten fazla\' biçimindedir. Seçeneklerdeki sorun hangisidir?', 'Sınır değerlerde (1 ve 2 saat) seçenekler çakışmaktadır', ['Seçenekler çok az sayıda olduğu için kapsayıcı değildir ve genişletilmelidir', 'Seçenekler sayısal olduğu için çözümlenemez', 'Seçenekler arasında \'3 saatten fazla\' yer almamaktadır'], 'Tam 1 ya da 2 saat çalışan biri iki seçeneğe uyar; \'0–59 dk, 1 saat–1 saat 59 dk\' gibi örtüşmeyen sınırlar kullanılmalıdır.'),
  ('Görüntülü çevrimiçi görüşmelerin yüz yüze görüşmelere göre başlıca avantajı nedir?', 'Uzaktaki katılımcılara yol masrafı olmadan ulaşılabilmesi', ['Bağlantı sorunlarının hiçbir koşulda ve hiçbir zaman yaşanmaması', 'Beden dilinin yüz yüze görüşmeden daha ayrıntılı ve net görülmesi', 'Katılımcıdan onam almanın gereksiz ve isteğe bağlı hâle gelmesi'], 'Çevrimiçi görüşme coğrafi engelleri kaldırır ve maliyeti düşürür; ancak bağlantı sorunları, sınırlı beden dili ve teknolojiye erişim gibi sınırlılıkları vardır.'),
  ('Telefonla yapılan derinlemesine görüşmelerde görüşmecinin özellikle dikkat etmesi gereken nokta hangisidir?', 'Görsel ipuçları olmadığından sözlü onaylarla dinlediğini belli etmek', ['Katılımcının yüz ifadesini ve beden dilini yakından izleyip not etmek', 'Görüşmeyi en fazla iki soruyla sınırlayıp hemen bitirmek', 'Katılımcının yanıtlarını sürekli ve hızla kesip yeni konulara geçmek'], 'Telefonda baş sallama gibi işaretler görülemez; \'anlıyorum\', \'evet\' gibi kısa sözlü tepkiler katılımcıya dinlendiğini hissettirir.'),
  ('\'Okul müdürü olsaydınız ilk neyi değiştirirdiniz?\' gibi bir görüşme sorusunun türü nedir?', 'Varsayımsal soru', ['Demografik (kişisel bilgi) soru', 'Filtre sorusu', 'Olgu sorusu'], 'Varsayımsal sorular katılımcıyı hayali bir duruma yerleştirerek düşüncelerini ve önceliklerini ortaya koymasını sağlar.'),
  ('Küçük çocuklarla yapılan görüşmelerde aşağıdakilerden hangisi önerilmez?', 'Uzun, soyut ve çok parçalı sorular sormak', ['Kısa ve somut sorular sormak', 'Resim ya da oyuncak gibi destekler kullanmak', 'Görüşmeyi kısa tutmak'], 'Çocukların dikkat süresi ve soyut düşünme becerileri sınırlıdır; uzun ve soyut sorular yanlış anlaşılmaya ve yönlendirmeye açıktır.'),
  ('Bir görüşme raporunda katılımcıların söylediklerinden doğrudan alıntılara yer verilmesinin başlıca işlevi nedir?', 'Yorumların veriye dayandığını okura göstermek', ['Raporun uzunluğunu ve sayfa sayısını yapay biçimde artırmak', 'Katılımcıların kimliklerini okura tanıtmak', 'Örneklem büyüklüğünü hesaplamayı sağlamak'], 'Doğrudan alıntılar, araştırmacının çıkarımlarının katılımcıların kendi ifadelerine dayandığını gösterir ve okurun yorumu değerlendirmesine olanak verir.'),
  ('Yapılandırılmış görüşme formu kullanan anketörlerin eğitiminde özellikle vurgulanması gereken nokta hangisidir?', 'Soruları yazıldığı gibi okumak ve yanıtları yorumsuz kaydetmek', ['Katılımcıyla tartışıp onu doğru yanıta ikna etmek', 'Soruları kendi ifadeleriyle değiştirip kısaltmak ve sadeleştirmek', 'Katılımcının yanıtını tahmin edip önceden işaretlemek'], 'Yapılandırılmış görüşmede standart uygulama esastır; anketörler soru ifadesini değiştirmemeli ve kendi görüşlerini yansıtmamalıdır.'),
  ('Bir görüşmeci, görüşme sonunda katılımcıya araştırmanın sonuçlarını nasıl öğrenebileceğini anlatıyor ve teşekkür ediyor. Bu kapanışın işlevi nedir?', 'Katılımcıya saygı göstermek ve araştırmacıya güveni korumak', ['Katılımcının bütün yanıtlarını değiştirmesini ve geri almasını istemek', 'Görüşmenin onamını geriye dönük olarak yeniden almak', 'Görüşmeyi yeniden başlatıp aynı soruları tekrar sormak'], 'Saygılı bir kapanış etik bir yükümlülüktür ve topluluğun gelecekteki araştırmalara katılma isteğini de olumlu etkiler.'),
  ('Bir görüşmede katılımcı soruyla ilgisiz bir konuya uzun süre girdiğinde görüşmecinin yapması gereken en uygun şey nedir?', 'Kibarca ve uygun bir anda konuyu araştırma sorusuna geri getirmek', ['Katılımcıyı hemen susturup görüşmeyi kesin olarak sonlandırmak', 'Kayıt cihazını kapatıp katılımcıyı dinlemeyi tamamen ve kesin olarak bırakmak', 'Katılımcının söylediklerini döküme hiç yazmayıp silmek'], 'Görüşmeci akışı nazikçe yönlendirir; bazen \'ilgisiz\' görünen konular önemli bağlam da taşıyabilir, bu nedenle hemen kesmek yerine dengeli davranılır.'),
  ('Odak grup görüşmelerinde katılımcı sayısının çok yüksek (ör. 20 kişi) tutulmasının sakıncası nedir?', 'Her katılımcıya yeterli konuşma süresi kalmaması', ['Görüşmenin kendiliğinden çok kısa sürmesi', 'Katılımcıların birbiriyle hiç etkileşime girmemesi', 'Sonuçların doğrudan evrene genellenebilir olması'], 'Kalabalık gruplarda tartışma dağılır, bazı katılımcılar hiç söz alamaz ve alt gruplar oluşur; bu yüzden genellikle 6–10 kişi önerilir.'),
  ('Seçim günü sandıktan çıkan seçmenlere kime oy verdiklerinin sorulduğu ankete ne ad verilir?', 'Sandık çıkış anketi', ['Panel (izleme) anketi', 'Delphi turu', 'Odak grup görüşmesi'], 'Sandık çıkış anketleri oy kullandıktan hemen sonra seçmenlere uygulanır ve sonuçların erken tahmini için kullanılır.'),
  ('Sandık çıkış anketlerinde anketörün yalnızca kendisine yaklaşmaya istekli görünen seçmenlerle görüşmesi yerine \'her beşinci çıkan seçmeni\' durdurması hangi örnekleme mantığını uygular?', 'Sistematik seçim', ['Kartopu örneklemesi', 'Kota örneklemesi', 'Kolay ulaşılabilir örnekleme'], 'Sabit aralıklarla seçim yapmak, anketörün kişisel tercihini ortadan kaldırır ve sistematik bir seçim sağlar.'),
  ('Bir lise müdürü, okulun 9–12. sınıflarından her sınıf düzeyinden rastgele 25 öğrenci seçerek görüş toplamak istiyor. Bu yaklaşım hangi yönteme en yakındır?', 'Tabakalı rastgele örnekleme', ['Küme örneklemesi', 'Kartopu (zincir) örneklemesi', 'Kota örneklemesi'], 'Sınıf düzeyleri tabakaları oluşturur ve her tabakadan rastgele seçim yapılır; bu tabakalı rastgele örneklemedir (tabakalar eşit büyüklükte seçildiği için orantısız olabilir).'),
  ('Bir dergi okurlarına \'Derginin hangi bölümünü beğeniyorsunuz?\' anketini derginin içine ekliyor ve geri gönderilen formları çözümlüyor. Bu verinin temel sınırlılığı nedir?', 'Yalnızca formu doldurmaya istekli okurları yansıtması', ['Okurların tamamının formu kesinlikle doldurup göndermesi', 'Formların tam sayım niteliği taşıması', 'Örneklem çerçevesinin tüm vatandaşları kapsaması'], 'Formu geri göndermek gönüllülüğe dayalıdır; dergiye en bağlı ya da en tepkili okurlar daha çok yanıt verir.'),
  ('Bir AVM yönetimi müşteri memnuniyetini ölçmek için yalnızca cumartesi öğleden sonraları girişte anket yapıyor. Sonuçların genellenebilirliğini artırmak için ne yapılmalıdır?', 'Anket gün ve saatlerini haftanın farklı dilimlerine yaymak', ['Anketi yalnızca cumartesi sabahları yapıp yineleme yapmamak', 'Örneklemi yalnızca sadık müşterilerle sınırlamak', 'Anketi bir kez yapıp sonucu yıllarca geçerli saymak'], 'Ziyaretçi profili gün ve saate göre değişir; zaman dilimlerini örneklemek farklı müşteri gruplarını kapsar.'),
  ('Bir öğrenci bir bilim fuarı projesi için okulunun öğrencilerine kahvaltı alışkanlıklarını soracak. Okul listesine erişebiliyor, 800 öğrenci var ve 80 öğrenciye ulaşabilecek. Hangi plan en savunulabilirdir?', 'Listeden rastgele 80 öğrenci seçip onlara ulaşmak', ['Kendi sınıfındaki 30 kişiye ve arkadaşlarına sormak', 'Kantinde kahvaltı yapan ilk 80 kişiye sormak', 'Okulun sosyal medya hesabında gönüllü anket açmak'], 'Listeye erişim varsa rastgele seçim yapılabilir; diğer seçenekler yanlı alt gruplardan (arkadaşlar, kantinde kahvaltı yapanlar, gönüllüler) veri toplar.'),
  ('Bir hayvan barınağı sahiplenme sonrası memnuniyetini öğrenmek için yalnızca barınağa teşekkür mesajı gönderen ailelere anket yolluyor. Bu örneklem en çok neyi abartır?', 'Ailelerin genel memnuniyet düzeyini', ['Sahiplenmelerin geri iade oranını', 'Barınakta çalışan personelin sayısını', 'Hayvanların ortalama yaşını'], 'Teşekkür mesajı gönderen aileler büyük olasılıkla memnun ailelerdir; memnun olmayanlar örnekleme girmediği için memnuniyet abartılır.'),
  ('Bir müzik festivali organizatörü festival alanında dolaşan bir anketörün \'kendisine uygun görünen\' kişileri seçip görüşmesini istiyor. Bu seçimin en olası yanlılık kaynağı nedir?', 'Anketörün kişisel tercihleri', ['Örneklem çerçevesinin çok güncel olması', 'Örneklemin tamamen rastgele seçilmiş olması', 'Katılımcıların kimliklerinin anonim kalması'], 'Anketör, farkında olmadan kendine yakın, cana yakın ya da yaklaşılması kolay kişileri seçebilir; bu da örneklemi bu kişilere doğru kaydırır.'),
  ('Bir ankette gelir sorusunun %35 oranında boş bırakıldığı, diğer soruların ise neredeyse tamamen yanıtlandığı görülüyor. Bu durum en çok neye işaret eder?', 'Sorunun katılımcılara hassas gelmesine', ['Anketin bütünüyle anlaşılmaz yazılmış olmasına', 'Örneklem çerçevesinin güncel olmamasına', 'Gözlemciler arası uyumun düşük olmasına'], 'Tek bir soruda yoğunlaşan madde yanıtsızlığı, sorunun hassas, anlaşılmaz ya da uygun seçenekten yoksun olduğunu düşündürür; gelir bilinen hassas sorulardandır.'),
  ('Bir ankete katılım için katılımcılara küçük bir hediye çeki verilmesinin temel amacı nedir?', 'Yanıt oranını artırmak', ['Katılımcıların belirli yanıtları vermesini sağlamak', 'Anketin süresini kısaltmak', 'Örneklem çerçevesini güncellemek'], 'Küçük teşvikler katılım isteğini artırır; teşvik yanıtların içeriğine bağlanmamalı ve baskı yaratacak kadar büyük olmamalıdır.'),
  ('Açık uçlu anket yanıtları çözümlenirken önce yanıtların bir bölümü okunarak kategoriler oluşturulup sonra tüm yanıtların bu kategorilere atanmasına ne ad verilir?', 'Kodlama', ['Tabakalama', 'Ağırlıklandırma', 'Pilot uygulama'], 'Kodlama, nitel yanıtların sayılabilir kategorilere dönüştürülmesidir; kod kitabı her kategorinin tanımını ve örneklerini içerir.'),
  ('Bir anketin girişinde araştırmacının kurumunu, iletişim bilgilerini ve anketin kim tarafından yürütüldüğünü belirtmesinin yanıt kalitesine olası katkısı nedir?', 'Katılımcının güven duyup ciddiyetle yanıt vermesi', ['Katılımcının araştırmacıyı memnun etmek için yanıt uydurması', 'Anketin uzunluğunun kendiliğinden azalması', 'Örneklemin kendiliğinden rastgele hâle gelmesi'], 'Kurumsal kimlik ve iletişim bilgisi, katılımcının araştırmanın meşru olduğuna güvenmesini sağlar ve katılım ile yanıt ciddiyetini artırır.'),
  ('Bir anket şirketi, ilk temas edilemeyen hanelere farklı gün ve saatlerde en az üç kez daha gidilmesini zorunlu kılıyor. Bu kuralın amacı nedir?', 'Evde bulunması zor kişilerin örneklemden düşmesini önlemek', ['Anketörlerin daha fazla ücret almasını sağlamak', 'Hanelerin ankete katılmaya zorlanmasını ve ikna edilmesini sağlamak', 'Örneklem büyüklüğünü yapay olarak küçültmek'], 'Tek ziyarette yalnızca evde sık bulunan kişilere ulaşılır; tekrar ziyaretler çalışanlar gibi grupların da örnekleme girmesini sağlar.'),
  ('Bir kurumun çalışan memnuniyeti anketinde yöneticilerin yanıtları tek tek görebileceği bilinirse sonuçlar nasıl etkilenebilir?', 'Çalışanlar olumsuz görüşlerini saklayabilir', ['Çalışanlar daha eleştirel yanıtlar verir', 'Sonuçlar hiçbir yönde değişmez', 'Yanıt oranı kesinlikle %100\'e çıkar ve herkes katılır'], 'Yanıtların kimlikle izlenebileceği kaygısı, olumsuz geri bildirimi bastırır; bu nedenle çalışan anketlerinde anonimlik güvencesi kritik önemdedir.'),
  ('Bir anket, \'Okulunuzdaki fen laboratuvarını ne kadar yeterli buluyorsunuz?\' sorusunu laboratuvarı olmayan okulların öğrencilerine de soruyor. Bu tasarım hatasını gidermenin yolu nedir?', 'Önce laboratuvar olup olmadığını soran bir filtre eklemek', ['Sorunun seçenek sayısını beşten ona çıkarmak', 'Soruyu anketin başına taşımak', 'Soruyu iki ayrı konuyu soran tek soruya dönüştürmek'], 'Filtre sorusu, laboratuvarı olmayanları ilgisiz sorudan atlatır ve anlamsız yanıtların veriye karışmasını önler.'),
  ('Bir gözlemcinin bir davranışın bir oturumda kaç kez gerçekleştiğini saymasına ne ad verilir?', 'Sıklık kaydı', ['Süre kaydı', 'Gecikme kaydı', 'Anekdot kaydı'], 'Sıklık (frekans) kaydı, belirli bir zaman diliminde davranışın kaç kez görüldüğünün sayılmasıdır.'),
  ('Bir araştırmacı bir öğrencinin ders boyunca toplam kaç dakika sırasından ayrıldığını ölçmek istiyor. Hangi kayıt türü bu amaca en uygundur?', 'Süre kaydı', ['Sıklık kaydı', 'Gecikme kaydı', 'Anekdot kaydı'], 'Süre kaydı, davranışın ne kadar sürdüğünü ölçer; sıklık kaydı ise yalnızca kaç kez görüldüğünü verir.'),
  ('Gözlem formuna \'gözlem tarihi, saati, yeri ve gözlemcinin adı\' bilgilerinin eklenmesinin amacı nedir?', 'Verilerin bağlamının bilinmesi ve sonradan karşılaştırılabilmesi', ['Gözlenen kişilerin kimliklerini kamuya açıklamak', 'Formu daha uzun ve resmî göstermek', 'Gözlemcinin gözlem sırasında yorum yapmasını sağlamak'], 'Bağlam bilgileri, farklı zaman ve gözlemcilerden gelen verilerin karşılaştırılmasını ve olası gözlemci farklılıklarının izlenmesini sağlar.'),
  ('Bir gözlemci bir çocuk parkında \'saldırgan davranış\' kaydedecek. Aşağıdaki tanımlardan hangisi gözlem için en uygun işlevsel tanımdır?', 'Başka bir çocuğa vurma, itme ya da tekme atma', ['Çocuğun içinde öfke biriktirmesi', 'Çocuğun kötü niyetli olması', 'Çocuğun ailesinden şiddet görmüş olması'], 'İşlevsel tanım, gözlemcinin doğrudan görebileceği eylemlerle yapılır; öfke, niyet ya da geçmiş deneyim gözlenemez.'),
  ('Bir araştırmacının bir okulun öğretmenler odasındaki etkileşimleri yalnızca bir gün gözlemleyip \'Bu okulda öğretmenler arasında işbirliği yok\' sonucuna varması neden zayıftır?', 'Tek bir günlük gözlem olağan örüntüleri yansıtmayabilir', ['Öğretmenler odası gözlem için hiç uygun olmayan bir yerdir', 'Gözlem sonuçlarının her zaman anketle aynı çıkması gerekir', 'İşbirliği hiçbir zaman gözlemle incelenemez'], 'Genelleyici bir sonuç için gözlemin farklı gün ve durumlara yayılması gerekir; tek gün olağandışı olabilir.'),
  ('Bir araştırmacı 300 tamamlanmış anket hedefliyor ve önceki çalışmalardan yanıt oranının %60 olacağını öngörüyor. En az kaç kişiyle temas kurulmalıdır?', '500', ['480', '360', '180'], 'Gerekli temas sayısı = 300 / 0,60 = 500 kişi.'),
  ('Bir anketin 600 kişilik örnekleminden 150\'si ilk hafta yanıt vermiştir. İlk hafta sonundaki yanıt oranı nedir?', '%25', ['%15', '%40', '%60'], '150 / 600 = 0,25, yani %25.'),
  ('Bir ilçede hanelerin %40\'ı kırsal, %60\'ı kentseldir. 500 hanelik orantılı tabakalı örneklemde kırsal tabakadan kaç hane seçilmelidir?', '200', ['300', '250', '40'], '500 × 0,40 = 200 kırsal hane.'),
  ('Bir araştırmacı bir okulda 30 kişilik bir sınıfta kızların oranının %40 olduğunu biliyor ve bu sınıftan orantılı tabakalı olarak 10 öğrenci seçecek. Kaç kız öğrenci seçilmelidir?', '4', ['3', '6', '12'], '10 × 0,40 = 4 kız öğrenci; kalan 6 öğrenci erkek olur.'),
  ('Bir öğrenci kulüp üyelerinin %75\'inin yeni etkinliği desteklediğini söylüyor; ancak bu oranı 4 kişiye sorarak elde etmiştir. Bu sonucun en önemli zayıflığı nedir?', 'Örneklem çok küçük olduğu için oran şansa çok bağlıdır', ['Oran %100 olmadığı için kesinlikle yanlıştır', 'Dört kişi kulübün tamamını oluşturduğu için tam sayımdır', 'Oranın yüzde olarak verilmesi kural dışıdır'], 'Dört kişiden üçünün desteği, bir kişinin farklı yanıtıyla %50\'ye ya da %100\'e kayabilir; bu kadar küçük örneklemde tahmin çok oynaktır.'),
  ('Bir anket çalışmasında katılımcıların doğum yerine göre analiz yapılacaktır. Bu bilgiyi toplayan soru hangi gruba girer?', 'Demografik soru', ['Tutum sorusu', 'Sondaj sorusu', 'Varsayımsal soru'], 'Doğum yeri, yaş, cinsiyet ve eğitim gibi arka plan özellikleri demografik sorularla toplanır.'),
  ('\'Yeni toplu taşıma hattının açılmasını ne ölçüde desteklersiniz?\' sorusu hangi tür bilgiyi ölçer?', 'Tutum', ['Davranış', 'Demografik özellik', 'Olgu bilgisi'], 'Destekleme derecesi kişinin bir konuya yönelik değerlendirmesini, yani tutumunu ölçer.'),
  ('\'Geçen ay toplu taşımayı kaç kez kullandınız?\' sorusu hangi tür bilgiyi ölçer?', 'Davranış', ['Tutum', 'Görüş', 'Duygu'], 'Soru kişinin gerçekleştirdiği bir eylemin sıklığını, yani davranışını sorar.'),
  ('Bir anketin aynı konuyla ilgili sorularının bir arada gruplanması ve konu geçişlerinde \'Şimdi size okul ortamıyla ilgili sorular soracağız\' gibi geçiş cümleleri kullanılmasının amacı nedir?', 'Katılımcının dikkatini yeni konuya yönlendirmek ve akışı kolaylaştırmak', ['Katılımcıyı belirli yanıtlara ikna etmek', 'Anketin süresini yapay olarak uzatıp katılımcıyı yormak', 'Örneklem çerçevesini değiştirmek'], 'Konu blokları ve geçiş cümleleri bilişsel yükü azaltır ve anketin mantıklı bir sohbet gibi ilerlemesini sağlar.'),
  ('Bir anket formunun görsel düzeninde soruların sıkışık yazılması ve yanıt kutularının küçük olması hangi soruna yol açabilir?', 'Soruların atlanması ve yanlış işaretlenmesi', ['Yanıt oranının kesinlikle artması', 'Sosyal beğenirlik eğiliminin tamamen ortadan kalkması', 'Örneklemin rastgele hâle gelmesi'], 'Okunaklı olmayan düzen, katılımcının soruları gözden kaçırmasına ya da yanlış kutuyu işaretlemesine neden olur; bu da ölçüm hatasını artırır.'),
  ('Bir araştırmacının araştırma sorusu \'Lise öğrencileri sınav kaygısını nasıl deneyimliyor ve anlamlandırıyor?\' biçimindedir. Bu soru hangi veri toplama yaklaşımına en uygundur?', 'Derinlemesine görüşmeler', ['Kapalı uçlu ulusal anket', 'Kantin satış kayıtları', 'Sistematik zaman örneklemesi'], '\'Nasıl deneyimliyor ve anlamlandırıyor\' sorusu öznel anlamlara yöneliktir; bu tür sorular katılımcının kendi anlatımına alan tanıyan görüşmelerle yanıtlanır.'),
  ('Bir araştırmacının sorusu \'Türkiye\'deki lise öğrencilerinin yüzde kaçı haftada 10 saatten fazla ek ders çalışıyor?\' biçimindedir. Hangi yaklaşım en uygundur?', 'Olasılıklı örneklemle uygulanan anket', ['Az sayıda öğrenciyle derinlemesine görüşme', 'Tek bir okulda etnografi', 'Uzmanlarla Delphi çalışması'], 'Bir oranı evren için tahmin etmek, temsil edici bir örneklemle standart soruların sorulmasını gerektirir.'),
  ('Bir öğretmen, öğrencilerinin grup çalışması sırasında kimin liderlik ettiğini anlamak istiyor. Grup çalışması sırasında hangi öğrencinin kaç kez öneri yaptığını ve kimin önerisinin kabul edildiğini kaydetmesi hangi yönteme örnektir?', 'Yapılandırılmış gözlem', ['Yapılandırılmamış görüşme', 'Doküman incelemesi', 'Sözlü tarih'], 'Önceden belirlenmiş davranışların (öneri yapma, önerinin kabulü) kaydedilmesi yapılandırılmış gözlemdir.'),
  ('Bir öğretmen veli toplantısında velilere sözlü olarak \'Çocuğunuz evde günde kaç saat ekran başında kalıyor?\' sorusunu herkesin önünde soruyor. Toplanan yanıtların güvenilirliğini en çok ne zayıflatır?', 'Velilerin diğer velilerin önünde olumlu görünme isteği', ['Velilerin soruyu tamamen anlamaması', 'Sorunun açık uçlu olması', 'Velilerin sayısının fazla olması'], 'Topluluk önünde verilen yanıtlar sosyal beğenirlikten güçlü biçimde etkilenir; adsız ve yazılı bir form daha dürüst yanıtlar getirebilir.'),
  ('Bir anket uygulamasında tüm görüşmecilerin aynı giriş metnini okuması ve aynı onam ifadesini kullanması hangi amaca hizmet eder?', 'Katılımcıların aynı bilgilendirmeyi almasını ve uygulamanın standart olmasını', ['Görüşmecilerin kendi görüşlerini ve beklentilerini katılımcılara aktarabilmesini', 'Örneklem büyüklüğünün artmasını', 'Yanıtların daha olumlu çıkmasını'], 'Ortak giriş metni hem etik açıdan herkesin eşit bilgilendirilmesini hem de görüşmeciler arasındaki uygulama farklılıklarının azalmasını sağlar.'),
  ('Bir araştırmacı katılımlı gözlem sırasında bir grup üyesinin kendisine bir sır verdiğini ve bunu araştırmada kullanmamasını istediğini fark ediyor. Etik açıdan doğru davranış nedir?', 'Bilgiyi araştırma verisi olarak kullanmamak', ['Bilgiyi kişinin adıyla ve olduğu gibi araştırma raporunda yayımlamak', 'Bilgiyi diğer üyelerle paylaşmak', 'Bilgiyi gizlice kayda almak'], 'Katılımcının açıkça kullanılmamasını istediği bilgiye saygı göstermek, gönüllülük ve güven ilkelerinin gereğidir.'),
  ('Bir araştırmacı bir görüşmeyi kayda alırken katılımcının ses kaydına izin vermediğini öğreniyor. En uygun davranış hangisidir?', 'Kaydı yapmadan ayrıntılı not alarak görüşmeyi sürdürmek', ['Kaydı gizlice yapmak', 'Görüşmeyi katılımcıyı ikna edene kadar ertelemek', 'Katılımcıyı araştırmadan çıkarmak zorunda olduğunu söylemek'], 'Katılımcının tercihine saygı esastır; ses kaydı olmadan da dikkatli not alma ve görüşme sonrası hemen genişletilmiş not yazma ile veri toplanabilir.'),
  ('Bir görüşmeci deprem bölgesinde kayıp yaşamış bir katılımcıyla görüşürken katılımcının ağlamaya başladığını görüyor. En uygun davranış hangisidir?', 'Ara vermeyi önermek ve devam edip etmemeyi katılımcıya bırakmak', ['Soruları hızla sorup görüşmeyi bitirmek', 'Konuyu değiştirmeden aynı soruyu tekrar ve ısrarla sormak', 'Kayıt cihazını açık bırakıp odadan çıkmak'], 'Duygusal açıdan zorlayıcı görüşmelerde katılımcının iyiliği önceliklidir; ara verme ve devam kararını katılımcıya bırakma etik bir gerekliliktir.'),
  ('Görüşmelerde katılımcıya \'tek bir doğru yanıt olmadığının\' görüşmenin başında açıkça söylenmesinin amacı nedir?', 'Katılımcının sınanıyormuş gibi hissetmesini önlemek', ['Katılımcının yanıtlarını kısaltmasını sağlamak', 'Görüşmenin süresini uzatmak ve daha çok konu konuşmak', 'Katılımcının onam vermesini gereksiz kılmak'], 'Katılımcılar bilgi sınavına girdiklerini düşünürse \'doğru\' olduğunu sandıkları yanıtları verir; bu açıklama kendi deneyimlerini anlatmalarını kolaylaştırır.'),
  ('Bir çevre kulübü, sahildeki çöp miktarını belgelemek için her ayın ilk pazar günü aynı 100 metrelik şeritteki atıkları türlerine göre sayıp kaydediyor. Bu çalışmada veri hangi yöntemle toplanmaktadır?', 'Sistematik gözlem ve sayım', ['Yarı yapılandırılmış görüşme ve döküm', 'Gönüllü yanıtlı çevrimiçi anket', 'Uzmanlarla yürütülen Delphi turları'], 'Önceden belirlenmiş bir alanda, düzenli aralıklarla ve kategorilere göre yapılan sayım sistematik gözlemdir.'),
  ('Bir ilçe sağlık müdürlüğü aşılama oranını öğrenmek için ebeveynlere \'Çocuğunuzun aşıları tam mı?\' diye soruyor. Yanıtları doğrulamak için en uygun ek veri kaynağı hangisidir?', 'Aşı kartı ya da sağlık kayıtları', ['Ebeveynlerin komşularının görüşleri', 'Çocukların kendi tahminleri', 'Ebeveynlerin sosyal medya paylaşımları'], 'Beyanlar bellek ve sosyal beğenirlik nedeniyle hatalı olabilir; belgeye dayalı kayıtlar beyanların doğrulanmasını sağlar.'),
  ('Bir anket sorusu \'Ailenizde kaç kişi yaşıyor?\' biçimindedir. Bazı katılımcılar yurt dışında çalışan ağabeylerini sayarken bazıları saymıyor. Bu belirsizliği gidermek için ne yapılmalıdır?', '\'Hane\' kavramını tanımlayıp kimin sayılacağını açıkça belirtmek', ['Soruyu tamamen anketten çıkarıp hiç sormamak', 'Seçenekleri birbirleriyle çakışacak biçimde yeniden yazmak', 'Yanıtları ortalamaya yuvarlayıp tümünü aynı kabul ederek çözümlemeye devam etmek'], 'Kavramların açık tanımı (\'Son altı aydır sizinle aynı evde yaşayan kişiler\') farklı yorumları önler ve yanıtları karşılaştırılabilir kılar.'),
  ('Bir kafe sahibi müşteri memnuniyetini ölçmek için masalara \'Bizi nasıl buldunuz?\' kartları bırakıyor. Yalnızca çok memnun ya da çok kızgın müşterilerin kartları doldurduğu fark ediliyor. Bu durum hangi örneklem türünün tipik sorununu gösterir?', 'Gönüllü yanıt örneklemi', ['Tabakalı rastgele örneklem', 'Sistematik örneklem', 'Küme örneklemi'], 'Gönüllü katılımda güçlü duygulara sahip olanlar daha çok yanıt verir; ortadaki çoğunluk sessiz kalır.'),
  ('Bir anket uygulamasında anketörlerin katılımcıların yanıtlarını yüksek sesle tekrar ederek onaylatması (\'Yani haftada üç gün, doğru mu?\') hangi amaca yöneliktir?', 'Kayıt hatalarını azaltmak', ['Katılımcıyı yanıtını değiştirmeye zorlamak', 'Görüşmeyi uzatmak', 'Katılımcının kimliğini doğrulamak'], 'Yanıtın geri okunması, anketörün yanlış duyma ya da yanlış işaretleme hatalarını görüşme sırasında düzeltmesini sağlar.'),
  ('Bir anket raporunda \'Veri 3–17 Mart tarihleri arasında toplanmıştır\' bilgisinin yer alması neden önemlidir?', 'Sonuçların hangi döneme ait olduğunu ve bağlamını göstermesi', ['Anketin daha uzun, daha ayrıntılı ve daha resmî görünmesini sağlaması', 'Katılımcıların kimliklerini açığa çıkarması', 'Hata payını sıfıra indirmesi'], 'Tutum ve davranışlar zamanla değişebilir; veri toplama tarihleri sonuçların bağlamını ve diğer araştırmalarla karşılaştırılabilirliğini belirler.'),
  ('Bir araştırmacının \'gözlem\' ile \'izlenim\' arasındaki farkı gözetmesi neden önemlidir?', 'İzlenim yoruma dayanır; gözlem ise kayıt altına alınabilir olgulara', ['İzlenim her zaman gözlemden daha güvenilir ve nesnel bir veri kaynağıdır', 'Gözlem yalnızca laboratuvarda, izlenim yalnızca sahada yapılabilir', 'İkisi arasında araştırma açısından hiçbir fark bulunmamaktadır'], 'Sistematik gözlem tanımlı davranışların kaydına dayanır ve başkalarınca denetlenebilir; izlenim ise kişisel ve çoğu zaman genelleyici bir yargıdır.'),
  ('Bir anketin sonunda katılımcılara \'Bu anketle ilgili eklemek istediğiniz bir şey var mı?\' biçiminde açık uçlu bir soru konmasının yararı nedir?', 'Kapalı sorularda yakalanamayan görüş ve sorunları ortaya çıkarmak', ['Anketi daha kısa ve hızlı doldurulur hâle getirmek', 'Katılımcıların kimliklerini doğrulamak ve iletişim bilgilerini kayda geçirmek', 'Örneklem büyüklüğünü kendiliğinden artırmak'], 'Son açık uçlu soru, araştırmacının öngörmediği konuları ve anketin kendisine yönelik geri bildirimleri toplar.'),
  ('Bir anket ekibi bir kentte haneleri seçerken haritadan rastgele sokaklar seçiyor, ancak bazı yeni sitelerin haritada henüz yer almadığını fark ediyor. Bu durum hangi hata türüyle ilgilidir?', 'Kapsam hatası', ['Madde yanıtsızlığı', 'Hale etkisi', 'Onaylama eğilimi'], 'Haritada olmayan yeni yerleşimlerde yaşayanların seçilme şansı yoktur; çerçeve evreni tam kapsamamaktadır.'),
  ('Bir kütüphaneci okuma salonundaki öğrencileri, salonun cam bölmesinin arkasından ve salona girmeden izleyip hangi masaların kullanıldığını kaydediyor. Bu gözlemin katılımsız sayılmasının nedeni nedir?', 'Gözlemci gözlenen etkinliğe dahil olmamaktadır', ['Gözlemci öğrencilerle sürekli sohbet etmektedir', 'Gözlemci kendini öğrenci gibi tanıtmaktadır', 'Gözlemci yalnızca anket uygulamaktadır'], 'Katılımsız gözlemde gözlemci ortamın etkinliklerinin bir parçası olmaz; yalnızca dışarıdan izler ve kaydeder.'),
  ('Bir belediyenin hizmetlerini değerlendirmek isteyen bir araştırmacı için anketin uygun olduğu durum hangisidir?', 'Sakinlerin hizmetlerden memnuniyet oranını geniş ölçekte belirlemek', ['Tek bir sakinin belediyeyle yaşadığı sorunun ayrıntılı öyküsünü dinlemek', 'Belediye çalışanlarının günlük iş akışını yerinde izlemek', 'Belediyenin 1930\'lardaki kararlarını incelemek'], 'Anket geniş bir kitleden standart bilgiyi toplamaya uygundur; ayrıntılı öykü için görüşme, iş akışı için gözlem, geçmiş kararlar için belge incelemesi daha uygundur.'),
  ('Bir araştırmacı ilkokul öğrencilerine yönelik bir ankette Likert ölçeği yerine gülen, düz ve üzgün yüz simgeleri kullanıyor. Bu uyarlamanın amacı nedir?', 'Küçük yaştaki katılımcıların ölçeği daha kolay anlamasını sağlamak', ['Ölçeğin yanıtlarını sayısallaştırılamaz hâle getirmek', 'Öğrencileri her soruda gülen yüzü seçmeye zorlamak ve yönlendirmek', 'Anketin süresini uzatmak'], 'Görsel ölçekler okuma ve soyut derecelendirme becerisi sınırlı çocuklar için daha anlaşılırdır; yanıtlar yine sayısal olarak kodlanabilir.'),
  ('Bir anket ekibi, anketin uygulanacağı köylerde önce muhtarlarla tanışıp çalışmayı anlatıyor ve köy kahvesinde bir tanıtım yapıyor. Bu adım en çok neyi kolaylaştırır?', 'Topluluğun güvenini kazanarak katılımı artırmayı', ['Örneklemin olasılıksız hâle gelmesini', 'Kapsam hatasının artmasını ve bazı hanelerin dışarıda kalmasını', 'Anketin daha uzun sürmesini'], 'Yerel kanaat önderlerinin bilgilendirilmesi, topluluğun araştırmacılara güven duymasını ve hanelerin görüşmeyi kabul etmesini kolaylaştırır.'),
  ('Bir öğrenci, okulunun öğrenci konseyi seçiminden önce yaptığı bir ankette yalnızca kendi kulübündeki arkadaşlarına sorup bir adayın \'kesin kazanacağını\' yazıyor. Bu çıkarımdaki temel hata nedir?', 'Tek bir çevreden oluşan uygun örneklemden genelleme yapılması', ['Anket sorularının açık uçlu olması', 'Adayın adının ankette yer alması', 'Anketin kâğıt yerine çevrimiçi yapılması'], 'Bir kulübün üyeleri birbirine benzer görüşler taşıyabilir; bu örneklemden tüm okul için kesin tahmin yapılamaz.'),
  ('Bir araştırmacı yeni bir mahalle kütüphanesinin açılışından önce ve sonra aynı 200 haneye kitap okuma alışkanlıklarını soruyor. Bu tasarım hangi anket türüne örnektir?', 'Panel anketi', ['Tek seferlik kesitsel anket', 'Trend (eğilim) anketi', 'Gönüllü çevrimiçi oylama'], 'Aynı haneler iki farklı zamanda ölçüldüğü için bu bir panel tasarımıdır.'),
  ('Bir anketin \'Evet\' ya da \'Hayır\' ile yanıtlanan sorularında katılımcılara \'Emin değilim\' seçeneği sunulmaması hangi soruna yol açabilir?', 'Kararsız kişilerin rastgele bir seçeneği işaretlemek zorunda kalması', ['Kararsız kişilerin yanıtlarının ayrı bir grup olarak kolayca görülmesi', 'Soruların kendiliğinden açık uçlu hâle gelip kodlanamaması', 'Örneklem büyüklüğünün yarıya inmesi ve hata payının artması'], 'Kararsız katılımcılar uygun seçenek bulamazsa gerçekte taşımadıkları bir görüşü bildirebilir ya da soruyu atlayabilir.'),
  ('Bir gözlemci okul kantininde sıra bekleyen öğrencilerin sırayı bozma davranışını kaydedecektir. Gözlemci etkisini azaltmak için en uygun konum hangisidir?', 'Kantinin olağan bir köşesinde, dikkat çekmeden oturmak', ['Sıranın tam önünde durup her öğrenciyi uyarmak', 'Öğrencilerle birlikte sıraya girip onları yönlendirmek', 'Her öğrenciye gözlem yaptığını tek tek söylemek ve not göstermek'], 'Gözlemcinin olağan bir yerde ve göze batmadan bulunması, öğrencilerin davranışlarını gözlemci yüzünden değiştirme olasılığını azaltır.'),
  ('Bir anket formunda ilk soru olarak \'Hiç yasa dışı madde kullandınız mı?\' sorusunun yer alması neden uygun değildir?', 'Güven oluşmadan hassas bir soruyla başlamak katılımı düşürebilir', ['İlk soruların her zaman açık uçlu olması zorunludur', 'Bu tür sorular yalnızca odak gruplarda sorulabilir', 'İlk soru her zaman yaş sorusu olmak zorundadır'], 'Anketler genellikle ilgi çekici ve zararsız sorularla başlar; hassas sorular güven oluştuktan sonra gelir.'),
  ('Bir görüşmecinin görüşme sırasında saatine sık sık bakması katılımcıya hangi mesajı verebilir?', 'Görüşmecinin acele ettiği ve ilgisinin azaldığı', ['Görüşmecinin katılımcıyı dikkatle ve ilgiyle dinlediği', 'Görüşmenin henüz başladığı ve uzun süreceği', 'Katılımcının yanıtlarının çok önemli bulunduğu'], 'Sözsüz işaretler katılımcının ne kadar ayrıntı vereceğini etkiler; acele izlenimi yanıtların kısalmasına yol açabilir.'),
  ('Bir anketin sonuçları erkek ve kadın katılımcılar için ayrı ayrı raporlanacaktır. Bu nedenle anket formunda hangi tür bir soru mutlaka bulunmalıdır?', 'Cinsiyeti soran demografik bir soru', ['Katılımcının en sevdiği rengi soran bir soru', 'Katılımcının görüşmeciyi beğenip beğenmediğini soran bir soru', 'Katılımcının adını ve soyadını soran bir soru'], 'Alt grup karşılaştırmaları için gruplamayı sağlayacak demografik bilgi toplanmalıdır; ad-soyad ise gerekli değildir ve gizliliği zayıflatır.'),
  ('Bir araştırmacının bir ilkokulda \'öğretmenlerin öğrencilere söz verme biçimini\' incelerken gözlem notlarına \'öğretmen erkek öğrencilere 9, kız öğrencilere 4 kez söz verdi\' yazması hangi tür kayda örnektir?', 'Sıklık kaydı', ['Süre kaydı', 'Gecikme kaydı', 'Yansıtıcı not'], 'Davranışın kaç kez görüldüğünün sayılması sıklık kaydıdır; burada söz verme sayıları gruplara göre ayrılmıştır.'),
];
